(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["nl"] = {"ui":{"skip":"Ga naar de inhoud","back":"← Terug naar AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies een taal","lang.search":"Zoek een taal","lang.none":"Geen taal gevonden","lang.notYet":"{name} is nog niet vertaald","theme.aria":"Wissel van thema: licht, donker of zwart","theme.toLight":"Naar het lichte thema","theme.toDark":"Naar het donkere thema","theme.toBlack":"Naar het zwarte thema (echt zwart, fijn voor OLED-schermen)","words.underline":"Onderstreep deze woorden op de pagina","words.underlineHelp":"Ga met je muis over een woord met een stippellijn, of tik erop, om te zien wat het betekent.","words.col.todo":"Kaarten voor nu: hier begint het team straks aan.","words.col.doing":"Een AI werkt nu aan deze kaart.","words.col.review":"De ene AI heeft het werk gedaan; een andere controleert het voordat het bij jou komt.","words.col.verify":"Wacht op jou: probeer het uit en zeg of het werkt.","words.col.team":"Jouw opmerkingen of antwoorden, die wachten tot het team ze oppakt.","words.col.done":"Af en goedgekeurd.","index.title":"AI-gile: je AI-devteam, op één bord","index.description":"AI-gile is een kanbanbord voor AI-codeerteams. Zij werken terwijl jij slaapt; jij krijgt één korte stapel met dingen om te beslissen, te testen en goed te keuren.","hero.logoAlt":"AI-gile-bordicoon","hero.h1.html":"Je AI-devteam, op één&nbsp;bord.","hero.alpha":"🐣 Gesloten pre-alpha","hero.alphaTitle":"Vroeg en onaf: fijn dat je het probeert!","hero.lede":"Ze bouwen terwijl jij slaapt. Je wordt wakker met één kort stapeltje: een paar vragen, een paar dingen om te testen, een paarse diamant of twee. Klikken, goedkeuren, terug naar je koffie.","dl.windows":"Windows-app","dl.browser":"Gebruik het in je browser","dl.messenger":"📱 Messenger voor je telefoon","dl.soon":"Binnenkort","dl.notify":"🔔 Laat het me weten als het opengaat","dl.notifySmall":"Alpha of bèta","hero.secondary":"Agile, maar het team heeft nooit een stand-upkoffie nodig. (Stand-ups houden ze toch.)","pitch.h2":"AI-gile in zoveel woorden als je wilt","pitch.lede":"Kies een lengte, van één woord tot 144. Elke lengte is een eigen beschrijving, speciaal voor die lengte geschreven. Sleep de schuifregelaar of gebruik de pijltjestoetsen.","pitch.rangeLabel":"Lengte in woorden","pitch.dice":"🎲 nog een versie","pitch.words.one":"{n} woord","pitch.words.other":"{n} woorden","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} teken","pitch.chars.other":"{n} tekens","count.line.html.one":"Nu {n} kaart op het bord","count.line.html.other":"Nu {n} kaarten op het bord","people.humans.html.one":"👥 {n} mens","people.humans.html.other":"👥 {n} mensen","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} nu aan het werk","people.working.html.other":"⚡ {n} nu aan het werk","pre.title":"AI-gile: hier wordt iets gebouwd","pre.description":"Hier wordt iets gebouwd: een bord waarop AI-teams bouwen wat je vraagt, en je onderweg dingen leren. Voorlopig een gesloten pre-alpha met vrienden.","pre.h1":"Hier wordt iets gebouwd. 🤫","pre.line":"Een bord waarop AI-teams bouwen wat je vraagt, en je onderweg dingen leren. Voorlopig een gesloten pre-alpha met vrienden.","pre.btn":"🔔 Laat het me weten als het opengaat","pre.peek":"Achter het glas: het echte bord, live. Elke kaart is een gekleurd balkje.","pre.peekFake":"Achter het glas: zo ziet een bord aan het werk eruit.","pre.night":"🌙 De nachtwaker heeft nu de leiding · 😴 de mens rust even","features.aria":"Wat het doet","f.pile.h":"Eén stapel voor jou","f.pile.html":"<b>Voor jou</b> verzamelt alles wat op jou wacht, uit al je projecten: vragen, dingen om te testen, taken die alleen een mens kan doen. Je wachtrij laat zien wat er nu aan de beurt is en hoe lang dat duurt.","f.sleep.h":"Teams die werken terwijl jij slaapt","f.sleep.p":"Elk project heeft een lead en een team van AI-agents. Reageer op een kaart en het team wordt wakker, doet het werk en geeft het terug met stappen die een moe mens kan volgen.","f.tester.h":"Een AI-tester kijkt eerst","f.tester.p":"Voordat iets bij jou komt, volgt een tester de stappen in een kopie van de app en laat hij zien wat hij zag, met een screenshot. Blader door de geslaagde en keur ze met één klik goed.","f.proof.h":"Bewijs, geen beloftes","f.proof.p":"Elke overdracht laat zien wat er veranderd is: de bestanden, de diff, de screenshots. Je hoeft niet elke app te openen om te kijken of iets af is.","f.chat.h":"Chat met je leads","f.chat.p":"Een balk in Discord-stijl: één icoon per project, paarse diamanten voor wat jou nodig heeft. Stuur een lead een idee; die maakt er kaarten en een plan van, met een ✅ Go-knop.","f.tidy.h":"Houdt zichzelf netjes","f.tidy.p":"Verwante kaarten worden samengevoegd, warrige titels rechtgezet en een tokencheck houdt de code slank. Minder heen en weer schakelen, minder om aan te denken.","f.private.h":"Van jou, op je eigen computer","f.private.li1":"Het bord draait op je eigen machine en luistert alleen naar jou.","f.private.li2":"Privéberichten tussen mensen zijn end-to-end versleuteld.","f.private.li3":"Geen accounts, geen trackers, geen cookies.","f.lang.h":"In jouw taal","f.lang.p":"Meer dan 120 talen, van Nederlands, Welsh en Japans tot piraat, Yoda en Klingon, met een snelle schakelaar terug naar het Engels voor het vakjargon.","f.service.h":"Van een idee naar een echte dienst","f.service.p":"Iets gebouwd met AI dat mensen nu gebruiken? Maak er een dienst van en het bord helpt je het goed te draaien: uptime-checks, een openbare statuspagina, incidenten met een verslag, wijzigingen die een Go nodig hebben, en elke dag gecontroleerde back-ups. Help legt elke stap uit terwijl je bezig bent.","msgr.h2":"AI-gile Messenger: je team in je broekzak","msgr.p1":"Praat met je AI-team zonder het bord te openen. Chat met je projectleads en je vrienden, en bekijk en beantwoord de teststappen van een kaart, allemaal vanaf je telefoon.","msgr.p2":"Koppelen doe je door een QR-code op je bord te scannen. De eerste keer? Een vriendelijke demochat laat je alles zien.","msgr.when":"Eerst Android, daarna een webversie voor telefoons en iPhone.","msgr.who":"Je projectlead","msgr.b1":"De fix voor de donkere modus is klaar. Wil je de teststappen?","msgr.b2":"Ja, graag!","msgr.b3":"1. Open Instellingen. 2. Kies Donker. Ziet het er goed uit?","tl.aria":"Tijdlijn van het eerste gesprek tot de roadmap","tl.h2":"Van het eerste gesprek tot wat er nog komt","tl.lede":"Echte datums en tijden, in je eigen tijdzone. Na vandaag is het de planning, zonder beloofde datums.","tl.today":"Vandaag","tl.planned":"gepland","tl.doing":"bezig","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarten","join.h2":"Doe mee","join.lede":"AI-gile wordt gebouwd door een bebaarde rare snuiter met AuDHD en een paar gevechten met zijn mentale gezondheid, en een flink aantal geduldige agents. Voorlopig is het privé: een gesloten alpha met vrienden. Zin om het te proberen als het opengaat?","join.btn":"Meld je interesse","join.small":"We mailen je, verder niets","footer.tag":"AI-gile. Geen trackers, geen cookies, geen stand-upkoffie.","footer.licence":"Zakelijke licentie","footer.status":"Status","footer.privacy":"Wat we bewaren","footer.thanks":"Bellen dankzij ChilledChat","form.sending":"Versturen…","form.failed":"Dat lukte niet: probeer het later opnieuw.","form.offline":"AI-gile was niet bereikbaar: probeer het later opnieuw.","form.keep":"We gebruiken dit alleen om je te antwoorden en verwijderen het daarna. Geen trackers, geen cookies.","form.keepLink":"Wat we bewaren","interest.title":"AI-gile: laat me weten wanneer de alpha opengaat","interest.description":"Laat je e-mailadres achter om te horen wanneer de gesloten alpha of bèta van AI-gile opengaat.","interest.h1":"🔔 Laat het me weten als het opengaat","interest.lede":"AI-gile zit in een gesloten pre-alpha. Laat je e-mailadres achter en we mailen je één keer, zodra er een plek voor je is.","interest.email":"Je e-mailadres","interest.which":"Welke test?","interest.alpha":"Gesloten alpha: vroeg, ruw, veel veranderingen","interest.beta":"Bèta: rustiger, later","interest.both":"Allebei goed, wat het eerst komt","interest.submit":"Zet me op de lijst","interest.thanks":"Bedankt! Je staat op de lijst.","licence.title":"AI-gile: zakelijke licentie","licence.description":"Gebruik je AI-gile voor je bedrijf? Vraag een gratis zakelijke licentie aan.","licence.h1":"📜 Zakelijke licentie","licence.lede":"Gebruik je AI-gile op je werk? Vertel ons wie je bent en wat je doet. Doet het iets goeds, dan is de licentie gratis.","licence.company":"Bedrijf","licence.website":"Website","licence.what":"Wat je doet","licence.how":"Hoe het de wereld helpt","licence.email":"E-mailadres","licence.submit":"Aanvragen","licence.thanks":"Bedankt! We antwoorden per e-mail.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles rustig","status.intro":"Werkt AI-gile op dit moment? Deze pagina controleert elke 5 minuten de website, het delen van borden, bellen en de download.","status.up":"Werkt (antwoordde in {ms} ms)","status.slow":"Gaf geen antwoord bij de laatste controle, we proberen opnieuw","status.down":"Onbereikbaar: gaf geen antwoord bij de laatste twee controles","status.svc.web":"Website","status.svc.web.offers":"Deze site: wat AI-gile is, en het interesseformulier","status.svc.boards":"Borden delen","status.svc.boards.offers":"Openbare borden, berichten tussen vrienden en uitnodigingen","status.svc.calls":"Bellen","status.svc.calls.offers":"Spraak, video en scherm delen in AI-gile","status.svc.download":"Download","status.svc.download.offers":"Het Windows-installatieprogramma en uitnodigingslinks","status.checking":"Controleren…","status.offline":"De statusdienst is nu niet bereikbaar (we proberen opnieuw)","status.updated":"bijgewerkt {ago}","status.justNow":"zojuist","status.min":"{n} min geleden","status.hours":"{n} uur geleden","status.days":"{n} d geleden","privacy.title":"AI-gile: wat we bewaren","privacy.h1":"Wat we bewaren","privacy.lede":"Kort gezegd: alleen wat je ons stuurt, en niet lang.","privacy.only":"Alleen wat je ons stuurt: wat je in een formulier typt, zoals je e-mailadres. Verder niets over jou.","privacy.sealed":"Het wordt verzegeld zodat onze server het niet kan lezen: in je browser, nog voor het vertrekt (in een oudere browser op het moment dat het aankomt). Alleen ons eigen bord kan het openen.","privacy.server":"Het wordt van de server verwijderd zodra het ons bord bereikt. Wat er na 30 dagen nog staat, wordt hoe dan ook verwijderd.","privacy.board":"We bewaren het op ons bord alleen tot we je hebben geantwoord, en verwijderen het daarna ook daar.","privacy.none":"Geen trackers, geen cookies, geen analytics.","privacy.local":"Je taal en je keuze voor licht of donker blijven in je eigen browser. Die worden nooit naar ons gestuurd.","privacy.ask":"Wil je dat het eerder weg is? Beantwoord onze e-mail en laat het ons weten.","live.h2":"Kijk live mee hoe het gebouwd wordt","live.caption":"Elke kaart is verborgen: je ziet de vorm van het werk, niet de woorden.","live.watching.one":"live: {n} kijkt mee","live.watching.other":"live: {n} kijken mee","live.last.now":"Laatste kaart zojuist verplaatst","live.last.min.one":"Laatste kaart {n} min geleden verplaatst","live.last.min.other":"Laatste kaart {n} min geleden verplaatst","live.last.hour.one":"Laatste kaart {n} uur geleden verplaatst","live.last.hour.other":"Laatste kaart {n} uur geleden verplaatst","live.last.day.one":"Laatste kaart {n} dag geleden verplaatst","live.last.day.other":"Laatste kaart {n} dagen geleden verplaatst","live.offline":"Het live bord neemt even een adempauze. Kom straks nog eens terug.","live.cols":"Backlog|Te doen|Bezig|Team checkt|Jij test|Voor het team|Klaar","footer.models":"AI-gile laat AI-modellen voor je werken. Wat ze zeggen en doen is van hen, dus controleer het voor je erop vertrouwt.","privacy.ai.h":"Het AI-deel","privacy.ai.models":"AI-gile is het bord. Het werk doen AI-modellen van andere bedrijven, zoals Claude, Codex en Gemini, op je eigen accounts.","privacy.ai.check":"Wat ze schrijven en doen komt van hen, en het kan fout zijn. Controleer het voor je erop bouwt of het uitbrengt.","privacy.ai.files":"Ze wijzigen bestanden en voeren opdrachten uit in de mappen die je koppelt. Maak een back-up.","privacy.ai.send":"Wat je aan een model geeft, gaat naar het bedrijf erachter, onder hun voorwaarden. Hun eigen voorwaarden en kosten gelden.","privacy.ai.asis":"AI-gile is een vroege testversie, zoals hij is."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Uitbesteed."]},{"n":2,"texts":["Robotkanban, gratis.","Jij beslist.","Ideeën, gebouwd."]},{"n":3,"texts":["Kanban voor robots.","Ideeën worden functies.","Gratis, lokaal, getest."]},{"n":5,"texts":["Een kanbanbord waar agents werken.","Jij schrijft kaarten. Agents bouwen.","Gratis, lokaal, getest, ietwat maf."]},{"n":8,"texts":["Een gratis kanbanbord waarop AI-agents het werk doen.","Schrijf een idee. Agents bouwen het. Jij keurt goed.","Agile voor één mens en veel geduldige robots."]},{"n":13,"texts":["Een kanbanbord op je eigen computer waar AI-agents de kaarten oppakken.","Schrijf een idee. Een team van agents bouwt het. Een tester checkt het.","Gratis, zonder accounts of trackers: een bord, wat robots, en jij de baas."]},{"n":21,"texts":["AI-gile is een kanbanbord om met AI-codeeragents te werken. Zij pakken de kaarten op; jij test ze en keurt ze goed.","Elk project krijgt een lead en een team van AI-agents. Reageer op een willekeurige kaart en het team gaat aan de slag.","Een gratis, persoonlijk takenbord dat op je eigen computer draait. Het werk doen robots. Ja zeggen, dat doe jij."]},{"n":34,"texts":["Je zet ideeën op een bord. Een team van AI-agents maakt er werkende functies van, test ze en geeft ze terug met stappen om uit te proberen. Pas als jij het zegt, is iets af.","AI-gile is een zelfgemaakt kanbanbord dat Rich bouwde met veel hulp van de agents die het nu aanstuurt. Het is gratis, draait op je computer en wordt gedeeld met vrienden, niet verkocht.","Stel je een gewoon kanbanbord voor, met kolommen van Backlog tot Klaar. Alleen pakken AI-agents de kaarten op. Ze melden hoe het gaat, vragen hulp als ze vastzitten en wachten altijd op jouw duim omhoog."]},{"n":55,"texts":["AI-gile is een kanbanbord waarop het team uit AI-agents bestaat. Elk project heeft een lead die het werk plant en helpers die het bouwen. Is een functie klaar, dan probeert een AI-tester hem uit en maakt een screenshot. Daarna belandt hij op jouw stapel. Keur hem goed, of reageer en ze gaan opnieuw aan de slag.","Het begon als een manier om veel AI-codeersessies tegelijk bij te houden, voor één persoon, en groeide uit tot een echt bord. Het draait op je eigen machine, vraagt geen account en heeft geen trackers. Het is gratis, voor vrienden en iedereen die nieuwsgierig is. Het is ook nog niet af: verwacht ruwe randjes en af en toe een verrassing.","Dit is de eerlijke versie. De ideeën moet je nog altijd zelf bedenken en de resultaten moet je nog altijd zelf controleren. AI-gile doet alles daartussen: het houdt de kaarten op orde, wekt de juiste agent als jij reageert, laat precies zien wat er veranderd is en houdt alles bij elkaar in één korte stapel voor jou."]},{"n":89,"texts":["AI-gile is een gratis kanbanbord dat op je eigen computer draait. In plaats van mensen heeft elk project een team van AI-agents: een lead die jouw ideeën omzet in kaarten en een plan, en helpers die de kaarten op volgorde van prioriteit oppakken. Is er iets gebouwd, dan volgt een AI-tester de teststappen en laat hij zien wat hij zag. Daarna ligt het op één stapel klaar: Voor jou. Jij keurt het goed, of je reageert en het team probeert het nog eens. Zonder jou komt niets in Klaar.","Een paar functies die je misschien niet verwacht. Een nachtwacht houdt de kolom Te doen gevuld terwijl jij slaapt, met kaarten waarvoor geen antwoord van jou nodig is. Een tokenteller laat zien hoeveel de agents vandaag en deze week hebben gebruikt, en in de Geen-tokensmodus houden ze op met verbruiken. Je kunt vrienden berichten sturen, en privéberichten zijn end-to-end versleuteld. Het bord spreekt zo'n 120 talen, waaronder Nederlands, Vlaams, piraat en Klingon. Niets daarvan kost een cent, en niemand probeert het je aan te smeren.","AI-gile is een klein, persoonlijk project, geen bedrijf. Rich wilde een paar AI-codeerprojecten in de gaten houden zonder steeds elke app te openen. Dus bouwden hij en de agents er een bord voor, en daarna bouwde het bord de rest van zichzelf. Het zit in een gesloten pre-alpha: het werkt, meestal, voor een handvol vrienden. Er is geen prijzenpagina, geen nieuwsbrief en geen groeiplan. Klinkt het handig? Dan kun je vragen of je het mag proberen zodra het wat verder opengaat."]},{"n":144,"texts":["AI-gile is een kanbanbord voor één mens en een heleboel AI-agents. Het draait op je eigen computer en is helemaal gratis. Je voegt projecten toe, en elk project krijgt een lead en een klein team. Je chat met de lead, een beetje zoals op Discord, en beschrijft een idee; de lead maakt er kaarten en een plan van en wacht tot jij op Go drukt. Het team werkt de kaarten af op volgorde van prioriteit, met een eenvoudige opdrachtregel die voor taalmodellen gemaakt is. Voordat er iets bij jou terugkomt, volgt een AI-tester de stappen in een kopie van de app en voegt hij een screenshot toe. Afgerond werk belandt op je stapel, met de gewijzigde bestanden en de diff. Jij keurt het goed, of je laat een reactie achter en het team wordt wakker en probeert het opnieuw. Alleen jij kunt een kaart naar Klaar verplaatsen.","Een dag met AI-gile, ongeveer. 's Avonds laat je een paar reacties achter: deze knop staat op de verkeerde plek, die lijst moet gesorteerd worden, en kan er een donkere modus komen? Je gaat naar bed. De agents lezen de reacties, voeren de wijzigingen door, testen ze en geven ze terug. Raakt Te doen leeg, dan vult de nachtwacht de kolom aan uit de backlog, met kaarten waarvoor geen antwoord van jou nodig is. 's Ochtends ligt er één korte stapel: een paar vragen en een paar dingen om uit te proberen, elk met stappen die een slaperig mens kan volgen en een screenshot waarop je ziet dat het werkt. Je klikt erdoorheen, keurt de goede goed en stuurt de rest terug. Een tokenteller laat zien wat het allemaal heeft gekost, en de Geen-tokensmodus is er voor magere weken. Dan ga je ontbijten. Daar kunnen de agents nog niet bij helpen.","Eerst wat AI-gile niet is. Het is geen start-up, het is niet te koop en niemand verzamelt je gegevens. Het is een gratis bord dat op je computer draait, zonder accounts, zonder trackers en zonder cookies. Wat het wel is: één overzichtelijke plek waar je al je AI-codeerprojecten tegelijk ziet, terwijl een team agents de kaarten afwerkt en jij de beslissingen neemt. Het voegt verwante kaarten samen, zet warrige titels recht en houdt in de gaten hoe slank de code blijft. Het spreekt zo'n 120 talen, van Nederlands en Vlaams tot piraat en Klingon. Vrienden kunnen elkaar berichten sturen, privé en versleuteld. Het is gebouwd door Rich en een groot aantal geduldige agents, grotendeels met het bord zelf. Het zit in een gesloten pre-alpha, dus hier en daar is het nog ruw. Klinkt het leuk? Vraag het dan vriendelijk, en misschien mag je er vroeg bij."]}],"quips":{"1":"Eén woord. Gedurfd. Misschien te gedurfd.","3":"Drie woorden. Nu al eerlijker dan de meeste productpagina's.","8":"Acht woorden. Nog altijd korter dan een stand-up.","21":"De lengtes zijn trouwens story points. Uiteraard.","55":"Vijfenvijftig woorden. Terwijl je dit las, zijn er twee kaarten afgerond.","144":"Dat was de lange. Een 233 is er niet. De agents liggen al in bed."}},"timeline":{"first-idea.name":"Het eerste idee","first-idea.line":"Het allereerste gesprek, voordat er ook maar één regel code was.","first-board.name":"Het eerste bord","first-board.line":"Een bord dat zijn eigen bouw bijhoudt: kaarten, kolommen, slepen en neerzetten, projecten.","team-roles.name":"Team en rollen","team-roles.line":"Agentprofielen, teamsjablonen, ruimtes en wie wat doet.","install.name":"Installeren en releases","install.line":"Een zip die een vriend kan installeren, automatische updates, kanalen en terugdraaien.","usage-saver.name":"Zuinig verbruik","usage-saver.line":"Meten wat runs kosten, de code slank houden, je limiet sparen.","friends.name":"Vrienden en delen","friends.line":"Privéberichten, een versleutelde relay, uitnodigingen, rollen en gedeelde projecten.","languages.name":"Talen","languages.line":"Elke schermtekst in een taalbestand, met Nederlands en Vlaams als eerste.","ai-tester.name":"AI-tester","ai-tester.line":"Een tester checkt elke overdracht eerst en laat zien wat hij zag.","website.name":"De website","website.line":"aigile.lol, de teaser en deze tijdlijn.","streaming.name":"Chat en streamen","streaming.line":"Discord, Twitch, OBS, streamermodus, GIF's en emoji's.","no-ai.name":"Editie zonder AI","no-ai.line":"Een bord voor mensen die zonder AI programmeren, en openbare borden.","night-watch.name":"Nachtwacht","night-watch.line":"Een nachtwaker en een Scrum Master houden de teams bij de les terwijl jij slaapt.","p-more.name":"Al het andere","p-more.line":"Kleinere ideeën die nog op hun beurt wachten.","p-android.name":"Telefoon en Android","p-android.line":"Je bord bereiken vanaf je telefoon, daarna een eigen Android-app.","p-release.name":"Alpha en verder","p-release.line":"Gesloten alpha, de live site, daarna de bèta.","p-languages.name":"Meer talen","p-languages.line":"Meer dan honderd talen, en een onderdompelingsmodus voor wie een taal leert.","p-engines.name":"Meer AI-engines","p-engines.line":"Kies per agent Claude, Codex of Gemini.","p-pro.name":"Werken als een pro","p-pro.line":"Risicolabels, merge-poorten, incidentkaarten en vangrails.","p-self.name":"Zorg voor jezelf","p-self.line":"Een moe-modus, herinneringen om goed voor jezelf te zorgen, en 4:20.","p-servers.name":"Servers en schaal","p-servers.line":"Globale serverinstellingen, rollen en plannen voor groei.","p-livestream.name":"Extra's voor streamen","p-livestream.line":"Twitch-chat, eigen emoji's en een openbaar live-overzicht."},"words":{"button":"📖 Vakjargon","h":"📖 Woorden uitgelegd","intro":"Gratis les in gewone taal: elk woord dat je tegenkomt, van een eerste idee tot een dienst waar mensen op rekenen, met Agile, bouwen, veiligheid en werken met AI onderweg.","search":"Zoek een woord…","none":"Geen woord gevonden.","close":"Sluiten","count":{"one":"{count} woord","other":"{count} woorden"},"groups":[{"id":"idea","name":"💡 Idee en verkenning"},{"id":"plan","name":"🗺️ Het werk plannen"},{"id":"agile","name":"🔁 Agile werken"},{"id":"build","name":"🛠️ Bouwen"},{"id":"test","name":"🧪 Testen en kwaliteit"},{"id":"change","name":"🔀 Veilig wijzigen"},{"id":"run","name":"🛎️ Een dienst draaiende houden"},{"id":"sec","name":"🔒 Beveiliging en privacy"},{"id":"ai","name":"🤖 Werken met AI"},{"id":"money","name":"💰 Geld en licenties"}],"list":[{"id":"discovery","g":"idea","word":"Verkenning","text":"De eerste fase waarin je uitzoekt welk probleem het oplossen waard is en voor wie, voordat er iets gebouwd wordt.","also":["discovery"]},{"id":"problemstmt","g":"idea","word":"Probleemstelling","text":"Een of twee zinnen over wie een probleem heeft, wat het is en waarom het ertoe doet, zodat iedereen op hetzelfde mikt.","also":["probleemstellingen","problem statement"]},{"id":"user","g":"idea","word":"Gebruiker","text":"Iemand die gebruikt wat je bouwt. Om hun behoeften draait het werk.","also":["gebruikers","user"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Iedereen die belang heeft bij hoe het werk uitpakt of erdoor geraakt wordt, zoals wie ervoor betaalt, het gebruikt of ondersteunt.","also":["stakeholders","belanghebbende","belanghebbenden"]},{"id":"persona","g":"idea","word":"Persona","text":"Een verzonnen maar realistische persoon die staat voor één soort gebruiker, zodat het team kan vragen: “zou Sam dit makkelijk vinden?”","also":["persona’s"]},{"id":"userresearch","g":"idea","word":"Gebruikersonderzoek","text":"Met echte mensen praten en kijken hoe ze werken, om te leren wat ze nodig hebben in plaats van te gokken.","also":["user research"]},{"id":"journey","g":"idea","word":"Klantreis","text":"De stappen die iemand zet om iets gedaan te krijgen, van er voor het eerst over horen tot klaar zijn, ook buiten je product. Teken je ze uit, dan zie je waar mensen vastlopen.","also":["klantreizen","user journey","customer journey"]},{"id":"painpoint","g":"idea","word":"Pijnpunt","text":"Iets waar mensen zich nu aan ergeren of door vertraagd worden. Goede producten nemen pijnpunten weg.","also":["pijnpunten","pain point"]},{"id":"assumption","g":"idea","word":"Aanname","text":"Iets wat je gelooft maar nog niet gecontroleerd hebt. Schrijf je aannames op, dan zie je wat je eerst moet testen.","also":["aannames"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothese","text":"Een beste gok die je wilt toetsen, met wat je verwacht dat er gebeurt, zoals “mensen schrijven zich in als de eerste maand gratis is”.","also":["hypotheses","hypothesen"]},{"id":"experiment","g":"idea","word":"Experiment","text":"Een kleine, geplande test om te leren of een idee werkt, voordat je er veel op inzet.","also":["experimenten"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Een snelle, ruwe proef om te zien of een idee überhaupt kan werken. Meestal gooi je hem weg zodra je het antwoord hebt.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"Een vroege versie van het product, vaak klikbare plaatjes, om het idee bij mensen uit te proberen voordat je het echt bouwt.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Een eenvoudige schets van een scherm die laat zien waar alles komt, zonder kleuren of echte inhoud.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Een gedetailleerd beeld van hoe een scherm eruit gaat zien, met echte kleuren en tekst, maar er werkt nog niets.","also":["mockups","mock-up"]},{"id":"bizcase","g":"idea","word":"Businesscase","text":"De redenen om een project te doen: wat het kost, wat het oplevert of bespaart, en de risico’s.","also":["businesscases","business case"]},{"id":"feasibility","g":"idea","word":"Haalbaarheid","text":"Of iets echt gebouwd en onderhouden kan worden met de tijd, het geld en de kennis die je hebt."},{"id":"outcome","g":"idea","word":"Resultaat","text":"De verandering die je voor mensen wilt, zoals minder gemiste afspraken. Dat telt meer dan hoeveel je bouwt.","also":["outcome"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Iets wat het team maakt, zoals een nieuw scherm of een rapport. Dat het er is, betekent nog niet dat het iemand helpt.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Succesmaatstaf","text":"Een getal dat laat zien of het werk deed waarvoor het bedoeld was, zoals meer mensen die hun bestelling afronden.","also":["succesmaatstaven","success metric"]},{"id":"kpi","g":"idea","word":"Kritieke prestatie-indicator (KPI)","text":"Een belangrijk getal dat je in de gaten houdt om te zien of het goed gaat, zoals aanmeldingen per week.","also":["KPI","KPI’s","KPI's"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKR’s)","text":"Een manier om doelen te stellen: het objective zegt wat je wilt, en een paar key results zijn de getallen die laten zien dat je er bent.","also":["OKR","OKR’s","OKR's"]},{"id":"product","g":"plan","word":"Product","text":"Wat er gebouwd en onderhouden wordt voor de gebruikers, zoals een app, een website of een hulpmiddel.","also":["producten"],"noTip":1},{"id":"vision","g":"plan","word":"Productvisie","text":"Een korte beschrijving van wie het product helpt en waar het op lange termijn naartoe gaat.","also":["product vision"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"De persoon die beslist wat er gebouwd wordt en in welke volgorde, zodat het team altijd werkt aan wat het belangrijkst is. In AI-gile ben jij dat.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Productmanager (PM)","text":"De persoon die de richting van een product bewaakt: welke problemen het oplost, voor wie en waarom. PM kan ook projectmanager betekenen, dus vraag welke.","also":["productmanagers","product manager"]},{"id":"projmgr","g":"plan","word":"Projectmanager","text":"De persoon die een project binnen tijd en budget houdt en bijhoudt wie wat doet en tegen wanneer.","also":["projectmanagers","projectleider"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"Een globaal plan van wat er de komende maanden aankomt, op volgorde. Het toont de richting, geen precieze data, en verandert terwijl je leert.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Mijlpaal","text":"Een moment in een project dat het markeren waard is, zoals “eerste versie live” of “100 gebruikers”.","also":["mijlpalen","milestone"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"De kleinste versie van een product die echte mensen al iets oplevert, zodat je vroeg van hen kunt leren.","also":["MVP","MVP’s","minimum viable product"]},{"id":"requirement","g":"plan","word":"Eis","text":"Iets wat het eindproduct moet doen of moet zijn.","also":["eisen","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"Wat er bij het werk hoort en, net zo belangrijk, wat niet.","also":["reikwijdte"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"Als er stukje bij beetje steeds meer bij het werk komt, zonder dat iemand de extra tijd of kosten afspreekt, zodat het nooit echt af raakt.","also":["sluipende uitbreiding"]},{"id":"feature","g":"plan","word":"Functie","text":"Eén ding dat het product voor mensen kan doen, zoals “je wachtwoord opnieuw instellen”.","also":["functies","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Een groot stuk werk, te groot voor één keer, dat daarom in kleinere kaarten wordt opgesplitst.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"Een klein stuk werk, geschreven vanuit de gebruiker: “Als klant wil ik mijn winkelmandje bewaren, zodat ik later kan afrekenen.” Het opent het gesprek over wat je gaat bouwen.","also":["user stories","gebruikersverhaal"]},{"id":"ac","g":"plan","word":"Acceptatiecriteria","text":"De controles waar één kaart aan moet voldoen om af te zijn, vooraf afgesproken, zoals “het mandje staat er nog na uit- en weer inloggen”.","also":["acceptatiecriterium","acceptance criteria"]},{"id":"task","g":"plan","word":"Taak","text":"Eén klus die gedaan moet worden, vaak een kleine stap van een groter verhaal.","also":["taken"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Een ander woord voor een kaart: één stuk werk of één verzoek, gevolgd van begin tot eind.","also":["tickets"]},{"id":"priority","g":"plan","word":"Prioriteit","text":"Hoe belangrijk of dringend iets is vergeleken met al de rest, zodat het belangrijkste werk eerst gaat.","also":["prioriteiten"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioriteren","text":"Werk op volgorde van belang zetten. Een bekende manier is MoSCoW: Must have, Should have, Could have, Won’t have (moet, zou moeten, zou kunnen, deze keer niet).","also":["prioritering","MoSCoW"]},{"id":"estimate","g":"plan","word":"Schatting","text":"Een beste gok van hoe groot een stuk werk is of hoe lang het duurt. Een gok, geen belofte.","also":["schattingen","inschatting"],"noTip":1},{"id":"storypoints","g":"plan","word":"Storypoints","text":"Een manier om de grootte van werk te schatten door kaarten met elkaar te vergelijken (“ongeveer twee keer zo groot als die”) in plaats van in uren. Ze zijn niet bedoeld om teams te vergelijken.","also":["storypoint","story points"]},{"id":"tshirt","g":"plan","word":"T-shirtmaten","text":"De grootte van werk schatten als S, M, L of XL. Snel, en goed genoeg voor een eerste planning.","also":["T-shirt sizing"]},{"id":"poker","g":"plan","word":"Planningpoker","text":"Een spel om te schatten: iedereen toont tegelijk een kaartje met een grootte, en wie het hoogst en het laagst zit, legt uit waarom.","also":["planning poker"]},{"id":"dependency","g":"plan","word":"Afhankelijkheid","text":"Als het ene stuk werk niet kan beginnen of afraken voordat een ander klaar is.","also":["afhankelijkheden"]},{"id":"blocker","g":"plan","word":"Blokkade","text":"Alles wat het werk nu tegenhoudt, zoals een ontbrekend antwoord of een kapot hulpmiddel.","also":["blokkades","blocker"]},{"id":"deadline","g":"plan","word":"Deadline","text":"De datum waarop iets af moet zijn.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Oplevering","text":"Iets concreets dat het werk oplevert en overdraagt, zoals een werkende pagina of een rapport.","also":["opleveringen","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Prognose","text":"Een voorspelling van wat er waarschijnlijk gebeurt, zoals wanneer het werk af is, op basis van wat je nu weet.","also":["prognoses","voorspelling","forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Meetwaarde","text":"Alles wat je meet en door de tijd heen volgt, zoals paginabezoeken of hoe lang een oplossing duurt.","also":["meetwaarden","metric","metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Wat mensen je vertellen over je werk, goed en slecht. Dat vroeg en vaak krijgen is het hart van Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"De wachtlijst met ideeën en werk dat nog niet ingepland is, het belangrijkste bovenaan. Er wordt pas aan gewerkt als het naar Te doen gaat."},{"id":"sprint","g":"agile","word":"Sprint","text":"Een korte, vaste periode werk (vaak een of twee weken, nooit meer dan een maand) met een doel en een afgesproken set kaarten om af te maken.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Een korte dagelijkse check-in: wat elk teamlid deed, wat ze nu gaan doen en wat hen tegenhoudt. In Scrum heet dat de daily scrum.","also":["standup","stand-ups","daily scrum","dagstart"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Een manier van werken waarbij kaarten over de kolommen van een bord schuiven (zoals Te doen, Bezig, Klaar) en het team beperkt hoeveel er tegelijk bezig is, zodat het werk blijft doorstromen."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP staat voor work in progress, werk in uitvoering. Een WIP-limiet is het maximum aantal kaarten in een kolom, zodat het team eerst afmaakt voor het meer begint.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"De korte checklist van het team voor wat “af” betekent, zoals getest en uitgelegd, voor een kaart bij jou komt. Zijn tweelingbroer, de Definition of Ready, zegt wanneer een kaart duidelijk genoeg is om te beginnen.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Een vaste terugblik op hoe het team werkt, om een of twee dingen af te spreken die de volgende keer beter kunnen. Kort voor retrospective. In AI-gile stelt een retro een aanpassing aan de werkwijze van het team voor, en jij zegt Go of Nog niet.","also":["retro's","retrospective"]},{"id":"swarm","g":"agile","word":"Zwerm","text":"Alle hens aan dek: veel mensen laten ander werk liggen om samen één dringend ding op te lossen tot het geregeld is. In AI-gile helpt elk team bij één project, en andere projecten wachten zolang.","also":["zwermen"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum de persoon die het team helpt goed te werken: ruimt op wat hen tegenhoudt, houdt overleggen op koers en coacht goede gewoontes, zonder de baas te spelen. In AI-gile ziet de Lead Scrum Master vastgelopen kaarten, geeft de teams een duwtje en herinnert je aan wat er wacht, in elk project.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Werken in kleine stappen: een beetje bouwen, vaak echte resultaten laten zien, leren van wat mensen zeggen en het plan onderweg bijsturen, in plaats van alles vooraf te plannen.","also":["agile werken"]},{"id":"manifesto","g":"agile","word":"Agile Manifest","text":"Een korte verklaring uit 2001 van softwaremakers. Ze zet mensen, werkende resultaten, nauw samenwerken met klanten en inspelen op verandering boven zware plannen en papierwerk.","also":["Agile Manifesto"]},{"id":"waterfall","g":"agile","word":"Watervalmethode","text":"De oudere manier van werken: eerst alles plannen, dan alles bouwen, dan alles testen, fase na fase. Laat nog iets veranderen is moeilijk en duur.","also":["waterval","waterfall"]},{"id":"iteration","g":"agile","word":"Iteratie","text":"Eén ronde van iets bouwen, nakijken en verbeteren. Agile werk is een reeks daarvan, en een sprint is er één soort van.","also":["iteraties"]},{"id":"increment","g":"agile","word":"Increment","text":"Een nieuw werkend stuk dat in een sprint of werkronde aan het product wordt toegevoegd en past bij wat er al was.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Een populaire Agile manier van werken: een klein team werkt in korte sprints naar een doel, met vaste rollen en een paar vaste overleggen om te plannen, te controleren en te verbeteren."},{"id":"scrumteam","g":"agile","word":"Scrumteam","text":"De kleine groep die in Scrum het werk doet: een product owner, een Scrum Master en de ontwikkelaars.","also":["scrumteams","Scrum team"]},{"id":"ceremonies","g":"agile","word":"Scrum-events","text":"De vaste overleggen in Scrum: de sprintplanning, de daily scrum, de sprintreview en de retro. Veel mensen noemen ze ceremonies.","also":["ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Sprintplanning","text":"Het overleg aan het begin van een sprint waarin het team afspreekt waarom de sprint ertoe doet, welke kaarten het oppakt en hoe het begint.","also":["sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Sprintdoel","text":"Eén zin die zegt waar een sprint voor dient. Kleine taken mogen onderweg veranderen, zolang het doel gehaald wordt.","also":["sprintdoelen","sprint goal"]},{"id":"sprintbacklog","g":"agile","word":"Sprintbacklog","text":"De kaarten die voor de huidige sprint gekozen zijn, met het plan van het team om ze te doen.","also":["sprint backlog"]},{"id":"productbacklog","g":"agile","word":"Productbacklog","text":"De volledige lijst, op volgorde, van alles wat er voor het product gebouwd kan worden, het belangrijkste bovenaan. Ze verandert terwijl je leert.","also":["product backlog"]},{"id":"productgoal","g":"agile","word":"Productdoel","text":"Het grotere resultaat waar het product naartoe werkt. Het helpt het team kiezen wat er daarna komt.","also":["productdoelen","product goal"]},{"id":"refinement","g":"agile","word":"Backlogverfijning","text":"Regelmatig de backlog doorlopen om kaarten op te ruimen, te splitsen, te ordenen en aan te vullen, zodat ze klaar zijn om op te pakken. Ook wel refinement genoemd.","also":["backlog refinement","refinement","backlog grooming"]},{"id":"sprintreview","g":"agile","word":"Sprintreview","text":"Een overleg aan het eind van een sprint waarin het team toont wat af is en hoort wat mensen ervan vinden, om te beslissen wat er volgt.","also":["sprintreviews","sprint review"]},{"id":"demo","g":"agile","word":"Demo","text":"Afgewerkt werk live laten zien aan de mensen die erom vroegen.","also":["demo’s"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Een vaste hoeveelheid tijd voor iets. Is die op, dan stop je, ook als nog niet alles af is.","also":["timeboxen","getimeboxt"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Hoeveel werk een team gewoonlijk in een sprint afmaakt, om te plannen hoeveel het de volgende keer oppakt. Het is geen score voor hoe hard mensen werken.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capaciteit","text":"Hoeveel werk het team in een periode kan oppakken, na vakanties en ander werk.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown-grafiek","text":"Een grafiek van het resterende werk in een sprint die dag na dag daalt. Blijft de lijn vlak, dan zit er iets vast.","also":["burndown","burndown chart"]},{"id":"burnup","g":"agile","word":"Burn-up-grafiek","text":"Een grafiek van afgewerkt werk dat stijgt door de tijd, naast het totaal dat gepland is, zodat je ziet wanneer je er bent.","also":["burnup","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Kanbanbord","text":"Het bord zelf: een kolom per fase van het werk, met kaarten die erover schuiven.","also":["kanbanborden","Kanban board"]},{"id":"pullsys","g":"agile","word":"Pullsysteem","text":"Een manier van werken waarin nieuw werk pas begint als iemand er ruimte voor heeft, in plaats van het op een vol bord te schuiven.","also":["pull system"]},{"id":"flow","g":"agile","word":"Flow","text":"Hoe soepel het werk over het bord beweegt. Goede flow betekent dat kaarten blijven doorschuiven in plaats van zich op te stapelen.","also":["doorstroming"],"noTip":1},{"id":"leadtime","g":"agile","word":"Doorlooptijd","text":"Hoe lang het duurt vanaf het moment dat iemand iets vraagt tot het af is.","also":["lead time"]},{"id":"cycletime","g":"agile","word":"Cyclustijd","text":"Hoe lang een kaart duurt vanaf het moment dat er echt aan gewerkt wordt tot ze af is.","also":["cycle time"]},{"id":"throughput","g":"agile","word":"Doorvoer","text":"Hoeveel kaarten er in een week, of een andere vaste periode, afraken.","also":["throughput"]},{"id":"bottleneck","g":"agile","word":"Knelpunt","text":"De ene fase waar werk zich opstapelt en alles erachter vertraagt, zoals de smalle hals van een fles.","also":["knelpunten","bottleneck"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Een rij dwars over het bord die kaarten van één soort groepeert, zoals dringend werk of de kaarten van één team.","also":["swimlanes"]},{"id":"lean","g":"agile","word":"Lean","text":"Een manier van werken die verspilling schrapt (alles wat de klant niet helpt) en het werk laat doorstromen."},{"id":"waste","g":"agile","word":"Verspilling","text":"In Lean: alles wat moeite kost maar de klant niet helpt, zoals wachten, overdoen of dingen bouwen die niemand gebruikt.","noTip":1},{"id":"kaizen","g":"agile","word":"Continu verbeteren","text":"Steeds een beetje beter worden met kleine, regelmatige aanpassingen, en dan nagaan of ze hielpen. Retro’s zijn een manier om dat te doen. Ook wel kaizen genoemd.","also":["continue verbetering","kaizen"]},{"id":"selforg","g":"agile","word":"Zelforganiserend team","text":"Een team dat zelf beslist hoe het het werk doet, in plaats van stap voor stap te horen wat het moet doen.","also":["zelforganiserend","zelfsturend team"]},{"id":"crossfunc","g":"agile","word":"Multidisciplinair team","text":"Een team met alle vaardigheden die het nodig heeft om het werk zelf af te maken, zoals ontwerpen, bouwen en testen.","also":["cross-functioneel team","multidisciplinair"]},{"id":"spike","g":"agile","word":"Spike","text":"Een kort onderzoekje met een vaste tijd, om een vraag te beantwoorden voordat je aan het echte werk begint.","also":["spikes"]},{"id":"rework","g":"agile","word":"Herwerk","text":"Werk opnieuw doen omdat het de eerste keer niet goed was.","also":["rework"]},{"id":"safe","g":"agile","word":"Opgeschaald Agile (SAFe)","text":"Manieren om Agile met veel teams in een grote organisatie te gebruiken. SAFe (het Scaled Agile Framework) is een bekend voorbeeld.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"De map met de code van het project en de volledige geschiedenis van commits. Ze kan op je computer staan, op GitHub, of op allebei.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Een aparte werklijn in de code, zodat je kunt veranderen zonder de hoofdversie aan te raken.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Een opgeslagen momentopname van de code, met een korte notitie over wat er veranderde. Je kunt er altijd naar terug.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Je opgeslagen momentopnames (commits) van deze computer naar de gedeelde kopie online sturen, zoals GitHub, zodat ze bewaard zijn en anderen erbij kunnen."},{"id":"merge","g":"build","word":"Merge","text":"De wijzigingen van de ene branch in een andere brengen, meestal terug in de hoofdversie."},{"id":"pr","g":"build","word":"Pull request","text":"Vragen om de wijzigingen van een branch na te kijken en in de hoofdversie op te nemen. Sommige sites noemen dat een merge request.","also":["PR","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"De code opruimen zonder te veranderen wat ze doet: kleinere bestanden, duidelijkere namen, minder herhaling."},{"id":"bug","g":"build","word":"Bug","text":"Iets dat niet werkt zoals het hoort.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Een tweede paar ogen: iemand anders dan de maker kijkt het werk na voor het bij jou komt, zodat er minder fouten doorglippen. In AI-gile controleert een andere AI elke kaart.","also":["code review"]},{"id":"code","g":"build","word":"Code","text":"De geschreven instructies die een computer vertellen wat hij moet doen. Ook wel broncode genoemd.","also":["broncode"],"noTip":1},{"id":"proglang","g":"build","word":"Programmeertaal","text":"Een taal om code in te schrijven, zoals JavaScript, Python of Java. Elke taal past bij andere klussen.","also":["programmeertalen"]},{"id":"developer","g":"build","word":"Ontwikkelaar (developer)","text":"Iemand die code schrijft en aanpast. Ook wel programmeur of software-engineer genoemd.","also":["ontwikkelaars","developer","developers","programmeur","programmeurs"]},{"id":"software","g":"build","word":"Software","text":"Programma’s die op computers en telefoons draaien, in tegenstelling tot de toestellen zelf (de hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Kort voor applicatie: een programma waarmee mensen iets gedaan krijgen, op een telefoon, een computer of in een webbrowser.","also":["apps","applicatie","applicaties"],"noTip":1},{"id":"webapp","g":"build","word":"Webapp","text":"Een app die in een webbrowser draait, zodat je niets hoeft te installeren.","also":["webapps","webapplicatie"]},{"id":"frontend","g":"build","word":"Front-end","text":"Het deel van een app dat je ziet en aanklikt: de schermen, knoppen en teksten, vaak in je browser.","also":["frontend","front end"]},{"id":"backend","g":"build","word":"Back-end","text":"Het deel van een app achter de schermen dat de gegevens bewaart en het werk doet als je iets aanklikt, zoals je wachtwoord controleren.","also":["backend","back end"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Zowel aan de front-end als aan de back-end werken.","also":["full-stack"]},{"id":"ui","g":"build","word":"Gebruikersinterface (UI)","text":"Wat iemand op het scherm ziet en gebruikt: de indeling, knoppen, menu’s en tekst.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Gebruikerservaring (UX)","text":"Hoe het voelt om iets te gebruiken: makkelijk, duidelijk en prettig, of verwarrend en traag.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Toegankelijkheid (a11y)","text":"Iets bruikbaar maken voor iedereen, ook voor mensen die slecht zien, geen muis kunnen gebruiken of een schermlezer gebruiken.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Pagina’s zo maken dat ze passen en goed werken op elk scherm, van een telefoon tot een groot beeldscherm."},{"id":"designsys","g":"build","word":"Designsysteem","text":"Een gedeelde set kleuren, lettertypes, knoppen en regels, zodat elk scherm er hetzelfde uitziet en zich hetzelfde gedraagt.","also":["designsystemen","design system"]},{"id":"architecture","g":"build","word":"Architectuur","text":"De grote lijnen van een systeem: wat de hoofdonderdelen zijn en hoe ze met elkaar praten."},{"id":"database","g":"build","word":"Database (DB)","text":"Een geordende opslag van informatie, zoals een heel krachtige spreadsheet die de app kan lezen en aanpassen.","also":["database","databases","databank","DB"]},{"id":"schema","g":"build","word":"Databaseschema","text":"De indeling van een database: welke tabellen met informatie erin zitten en wat er in elke tabel komt.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Kort voor structured query language: de taal waarmee je veel databases om informatie vraagt of die aanpast.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Gegevens","text":"Informatie die een computer bewaart, zoals namen, bestellingen of instellingen.","also":["data"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Een computer die altijd aanstaat en verzoeken van andere computers beantwoordt, zoals een webpagina sturen als je die bezoekt.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"De kant die iets vraagt, meestal je browser of app, die met een server praat. In het zakenleven betekent het ook gewoon klant.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kort voor application programming interface: een vaste menukaart van verzoeken die het ene programma aan het andere kan doen, zoals een weerdienst om de verwachting van vandaag vragen.","also":["API’s","API's","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Eén gerecht op de menukaart van een API: een webadres dat een programma kan aanroepen om iets op te halen of te versturen.","also":["endpoints"]},{"id":"integration","g":"build","word":"Koppeling","text":"Twee systemen met elkaar verbinden zodat ze samenwerken, zoals je webwinkel die bestellingen doorstuurt naar je boekhoudpakket.","also":["koppelingen","integratie","integraties"]},{"id":"webhook","g":"build","word":"Webhook","text":"Een bericht dat het ene systeem vanzelf naar het andere stuurt zodra er iets gebeurt, zoals “betaling ontvangen”.","also":["webhooks"]},{"id":"library","g":"build","word":"Bibliotheek","text":"Kant-en-klare code van iemand anders die je kunt hergebruiken in plaats van ze zelf te schrijven.","also":["bibliotheken","library"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Een kant-en-klaar raamwerk om een app te bouwen dat grotendeels bepaalt hoe de code in elkaar zit, zoals het geraamte van een huis dat je invult.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"Een gereedschapskist met tools, code en voorbeelden om software te bouwen voor één platform of dienst.","also":["SDK","SDK’s"]},{"id":"softdep","g":"build","word":"Softwareafhankelijkheid","text":"Een bibliotheek of tool die je code nodig heeft om te werken. Ze bijwerken is belangrijk voor de veiligheid.","also":["softwareafhankelijkheden","dependency","dependencies"]},{"id":"package","g":"build","word":"Pakket","text":"Een bundel kant-en-klare code die je in een project kunt installeren en gebruiken.","also":["pakketten","package"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pakketbeheerder","text":"Een tool die de pakketten waar je code op steunt ophaalt en bijwerkt. npm is een bekende.","also":["package manager","npm"]},{"id":"git","g":"build","word":"Git","text":"Het meest gebruikte hulpmiddel om de geschiedenis van codewijzigingen bij te houden, als commits en branches."},{"id":"github","g":"build","word":"GitHub","text":"Een website die Git-repo’s online bewaart, zodat teams code kunnen delen, wijzigingen nakijken en werk opvolgen."},{"id":"vcs","g":"build","word":"Versiebeheer","text":"Een volledige geschiedenis bijhouden van elke wijziging aan de bestanden, zodat je ziet wie wat veranderde en zo nodig terug kunt. Git doet dat.","also":["version control"]},{"id":"clone","g":"build","word":"Clonen","text":"Je eigen volledige kopie van een repo, met de geschiedenis erbij, op je computer zetten.","also":["clone","gekloond","klonen"]},{"id":"pull","g":"build","word":"Pull","text":"De nieuwste commits van de gedeelde kopie (zoals GitHub) naar je computer halen. Het omgekeerde van push.","also":["pullen"],"noTip":1},{"id":"mainbranch","g":"build","word":"Hoofdbranch","text":"De officiële versie van de code waar iedereen van vertrekt, vaak main of master genoemd.","also":["main branch","master branch"]},{"id":"conflict","g":"build","word":"Mergeconflict","text":"Als twee wijzigingen dezelfde regels op een andere manier aanpassen, zodat de computer ze niet kan samenvoegen en een mens moet kiezen.","also":["mergeconflicten","merge conflict"]},{"id":"diff","g":"build","word":"Diff","text":"Een overzicht van precies wat er tussen twee versies veranderde: regels erbij en regels eraf.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Je eigen kopie van de repo van iemand anders, die je kunt aanpassen zonder aan die van hen te komen.","also":["forks","geforkt"]},{"id":"script","g":"build","word":"Script","text":"Een kort programma dat vanzelf één klus doet, zoals bestanden opruimen of de app starten.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"De code omzetten in iets wat klaar is om te draaien, of dat resultaat zelf.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compileren","text":"Code die mensen schreven vertalen naar een vorm die de computer rechtstreeks kan uitvoeren.","also":["compiler"]},{"id":"cli","g":"build","word":"Opdrachtregel (CLI)","text":"Een tekstvenster waarin je opdrachten voor de computer typt in plaats van te klikken. Ook wel de terminal genoemd.","also":["opdrachtregel","command line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuratie (config)","text":"De instellingen die bepalen hoe software zich gedraagt, apart van de code bewaard zodat je ze makkelijk aanpast.","also":["config","configuratie"],"noTip":1},{"id":"envvar","g":"build","word":"Omgevingsvariabele","text":"Een instelling die een programma bij het starten meekrijgt, vaak voor adressen of wachtwoorden, zodat die niet in de code staan.","also":["omgevingsvariabelen","environment variable"]},{"id":"debugging","g":"build","word":"Debuggen","text":"Uitzoeken waarom iets niet werkt, en het oplossen.","also":["debugging","gedebugd"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Twee mensen (of een mens en een AI) die samen aan dezelfde code werken: de ene typt, de andere kijkt mee.","also":["pairing","samen programmeren"]},{"id":"docs","g":"build","word":"Documentatie (docs)","text":"Geschreven uitleg over hoe iets werkt of hoe je het gebruikt.","also":["documentatie","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Het eerste bestand om te lezen in een repo: wat het project is en hoe je het aan de praat krijgt.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacysysteem","text":"Een ouder systeem dat nog in gebruik is maar moeilijk te veranderen, vaak omdat nog maar weinig mensen het begrijpen.","also":["legacysystemen","legacy code","verouderd systeem"]},{"id":"techdebt","g":"build","word":"Technische schuld","text":"Snelle oplossingen die nu tijd besparen maar latere wijzigingen trager maken, zoals een lening waar rente op komt. Refactoren lost ze af.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Een controle of iets werkt zoals het hoort. Sommige tests draait de computer vanzelf telkens de code verandert; bij andere probeer jij een afgewerkte kaart uit voor je ze goedkeurt.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kort voor quality assurance (kwaliteitsbewaking): alles wat je doet om zeker te zijn dat het werk klopt voor het live gaat. In AI-gile zijn dat de automatische controles: staat QA op rood, dan ging er iets mis en kan het pas live als dat opgelost is.","also":["kwaliteitscontroles"]},{"id":"testpile","g":"test","word":"Teststapel","text":"De afgewerkte kaarten die wachten tot jij ze uitprobeert, de ene na de andere. Keur er een goed of stuur ze terug met een notitie, en de volgende komt eraan.","also":["teststapels"]},{"id":"autotest","g":"test","word":"Geautomatiseerde test","text":"Een controle die de computer vanzelf uitvoert telkens de code verandert, om fouten vroeg te vangen.","also":["geautomatiseerde tests","automatische test","automatische tests"]},{"id":"manualtest","g":"test","word":"Handmatige test","text":"Iemand die het werk met de hand uitprobeert om te zien of het doet wat het moet doen.","also":["handmatige tests","handmatig testen"]},{"id":"unittest","g":"test","word":"Unittest","text":"Een kleine automatische controle van één klein stukje code op zich.","also":["unittests","unit test"]},{"id":"integtest","g":"test","word":"Integratietest","text":"Een controle of verschillende onderdelen goed samenwerken, niet alleen elk apart.","also":["integratietests"]},{"id":"endtoend","g":"test","word":"End-to-endtest (E2E)","text":"Een test die doet alsof hij een echte gebruiker is, van begin tot eind, zoals aanmelden, kopen en betalen.","also":["E2E"]},{"id":"uat","g":"test","word":"Gebruikersacceptatietest (UAT)","text":"De mensen die om het werk vroegen, proberen het zelf en zeggen of het doet wat ze nodig hebben. De teststapel in AI-gile is daar de eigen versie van.","also":["UAT","acceptatietest","acceptatietests"]},{"id":"regression","g":"test","word":"Regressie","text":"Iets wat vroeger werkte maar na een wijziging stukging. Regressietests controleren of het oude nog werkt.","also":["regressies","regressietest","regressietests"]},{"id":"smoke","g":"test","word":"Smoketest","text":"Een heel snelle controle of de belangrijkste dingen überhaupt werken, bijvoorbeeld net nadat een wijziging live ging. Mislukt hij, stop dan en kijk.","also":["smoketests","smoke test"]},{"id":"exploratory","g":"test","word":"Verkennend testen","text":"Het product vrij uitproberen en er op allerlei manieren in porren, om problemen te vinden die geplande controles zouden missen.","also":["exploratory testing","verkennende test"]},{"id":"testcase","g":"test","word":"Testgeval","text":"Eén uitgeschreven scenario om te proberen: de stappen, en wat er moet gebeuren.","also":["testgevallen","testcase","test case"]},{"id":"coverage","g":"test","word":"Testdekking","text":"Hoeveel van de code door automatische tests gecontroleerd wordt. Meer is meestal veiliger, maar een hoge dekking alleen bewijst niet dat het goed werkt.","also":["test coverage"]},{"id":"testdata","g":"test","word":"Testgegevens","text":"Verzonnen voorbeeldinformatie om mee te testen, zodat de privégegevens van echte mensen niet bloot komen te liggen.","also":["testdata"]},{"id":"edgecase","g":"test","word":"Randgeval","text":"Een ongewone situatie aan de grens, zoals een leeg formulier of een naam met een apostrof, waar dingen vaak stukgaan.","also":["randgevallen","edge case"]},{"id":"happypath","g":"test","word":"Happy path","text":"De normale route waarbij alles goed gaat. Goed testen probeert ook de routes waar het misloopt."},{"id":"perftest","g":"test","word":"Performancetest","text":"Controleren hoe snel iets is en hoe goed het zich houdt onder druk.","also":["performancetests","prestatietest"]},{"id":"loadtest","g":"test","word":"Belastingstest","text":"Controleren hoe een systeem zich houdt als heel veel mensen het tegelijk gebruiken.","also":["belastingstests","loadtest","load test"]},{"id":"sectest","g":"test","word":"Beveiligingstest","text":"Zoeken naar zwakke plekken waardoor iemand een systeem kan misbruiken of kan zien wat niet voor hem bedoeld is.","also":["beveiligingstests","security test"]},{"id":"accesstest","g":"test","word":"Toegankelijkheidstest","text":"Controleren of mensen met verschillende beperkingen het product kunnen gebruiken, ook met een schermlezer of alleen een toetsenbord.","also":["toegankelijkheidstests"]},{"id":"linting","g":"test","word":"Linting","text":"Een automatische controle die waarschijnlijke fouten en slordige stijl in code opspoort, zoals een spellingcontrole voor programma’s.","also":["linter","linten"]},{"id":"static","g":"test","word":"Statische analyse","text":"Code automatisch nalezen op problemen, zonder ze uit te voeren.","also":["static analysis"]},{"id":"flaky","g":"test","word":"Wispelturige test","text":"Een test die soms slaagt en soms faalt zonder duidelijke reden, zodat je hem niet helemaal kunt vertrouwen.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Reproduceren (repro)","text":"Een bug met opzet opnieuw laten gebeuren door dezelfde stappen te volgen, zodat hij onderzocht en opgelost kan worden. Die stappen opschrijven is het nuttigste deel van een bugmelding.","also":["repro","reproduceren","stappen om te reproduceren"]},{"id":"severity","g":"test","word":"Ernst","text":"Hoe erg het gevolg van een probleem is, van een kleine ergernis tot alles dat stilvalt.","also":["ernstniveau","severity"]},{"id":"deploy","g":"change","word":"Deploy","text":"Een nieuwe versie van de software op de computers zetten waar ze draait, zoals een testkopie of de live dienst."},{"id":"release","g":"change","word":"Release","text":"Een bundel afgewerkt werk met een naam, die samen live gaat, met korte notities over wat er veranderde. 🚀 Releases schrijft die notities op basis van de afgewerkte kaarten.","also":["releases"]},{"id":"rollback","g":"change","word":"Terugdraaien","text":"Teruggaan naar de laatste versie die werkte als een nieuwe voor problemen zorgt. In AI-gile zet Terugdraaien de stappen om terug te keren die bij elke wijziging staan samen in één checklist.","also":["teruggedraaid"]},{"id":"live","g":"change","word":"Live","text":"De echte versie die mensen gebruiken, in tegenstelling tot een kopie om dingen uit te proberen. Ontwikkelaars noemen dat ook productie.","also":["productie"],"noTip":1},{"id":"change","g":"change","word":"Wijziging","text":"Een geplande aanpassing aan iets waar mensen op rekenen, eerst opgeschreven: wat, waarom, het risico, wanneer, en hoe je het ongedaan maakt. Begin er een met 🔀 Wijziging aanvragen.","also":["wijzigingsverzoek","wijzigingsverzoeken"],"noTip":1},{"id":"risk","g":"change","word":"Risico","text":"Iets wat mis kan gaan, met een score voor hoe waarschijnlijk en hoe erg het zou zijn. ⚠️ Risico's houdt ze bij in één lijst, hoogste score eerst, elk met een datum om opnieuw te kijken.","also":["risico's","risicoregister"]},{"id":"chgwin","g":"change","word":"Wijzigingsvenster","text":"De momenten waarop wijzigingen live mogen, zoals een rustige dinsdagavond. Buiten een venster kan een wijzigingskaart niet afgerond worden, behalve bij een noodgeval.","also":["wijzigingsvensters"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Een laatste controle net voor een wijziging live gaat: iedereen die moet goedkeuren zegt Go of No go. Het gaat pas door als iedereen Go zegt.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Goedkeuring","text":"Wachten op een ja voor het werk begint. Een kaart van een vriend, of een wijziging, wacht in ✅ Goedkeuringen tot jij ze goedkeurt of afwijst.","also":["goedkeuringen"]},{"id":"quiettime","g":"change","word":"Stille tijd","text":"Een periode, zoals tijdens een livestream, een demo of ’s nachts, waarin niets live gaat. De teams werken en testen gewoon door, maar live gaan wacht tot het voorbij is. Elders heet dat een wijzigingsstop.","also":["stille tijden","wijzigingsstop"]},{"id":"devops","g":"change","word":"DevOps","text":"Een manier van werken waarbij wie de software bouwt en wie ze draaiende houdt één team vormen, met veel automatisering, zodat wijzigingen vaak en veilig live gaan."},{"id":"cicd","g":"change","word":"CI/CD (continue integratie en levering)","text":"De wijzigingen van iedereen worden vaak samengevoegd in de hoofdversie en telkens automatisch gecontroleerd (continue integratie), zodat de software altijd klaar is om met één druk op de knop live te gaan (continue levering).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","continue integratie"]},{"id":"contdeploy","g":"change","word":"Continue deployment","text":"Een stap verder dan continue levering: elke wijziging die door de controles komt, gaat vanzelf live, zonder op een knop te drukken.","also":["continuous deployment"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"De automatische reeks stappen die een wijziging doorloopt op weg naar live, zoals bouwen, testen en dan deployen.","also":["pipelines"]},{"id":"environment","g":"change","word":"Omgeving","text":"Een aparte kopie van het systeem voor één doel, zoals een om in te bouwen, een om in te testen en de live omgeving.","also":["omgevingen"],"noTip":1},{"id":"devenv","g":"change","word":"Ontwikkelomgeving","text":"De kopie waarin een ontwikkelaar werkt, vaak op de eigen computer, waar iets stukmaken niemand schaadt.","also":["dev-omgeving","development environment"]},{"id":"testenv","g":"change","word":"Testomgeving","text":"Een aparte kopie van het systeem, alleen om te testen, zodat de echte dienst onaangeroerd blijft.","also":["testomgevingen"]},{"id":"staging","g":"change","word":"Staging","text":"Een laatste kopie die net zo is ingericht als live, voor een laatste controle voordat een wijziging live gaat.","also":["stagingomgeving","acceptatieomgeving"]},{"id":"artifact","g":"change","word":"Build-artefact","text":"Het bestand of de bundel die een build oplevert, klaar om te bewaren, te controleren of live te zetten.","also":["build-artefacten","artifact"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Een dringende oplossing die snel live gaat, buiten de normale planning, omdat er iets belangrijks stuk is.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Een kleine update die een bug oplost of een beveiligingslek dicht. Beveiligingspatches snel installeren is belangrijk.","also":["patches","beveiligingspatch"]},{"id":"version","g":"change","word":"Versienummer","text":"Een label zoals 2.4.1 dat zegt welke release je hebt. Vaak verandert het eerste getal bij grote wijzigingen en het laatste bij kleine oplossingen.","also":["versienummers"]},{"id":"relnotes","g":"change","word":"Releasenotes","text":"Een korte, eenvoudige lijst van wat er in een release veranderde, voor de mensen die het gebruiken, met oplossingen en bekende beperkingen. Ook wel changelog genoemd.","also":["release notes","changelog","wijzigingslog"]},{"id":"flag","g":"change","word":"Feature flag","text":"Een aan-uitschakelaar voor een functie, zodat nieuw werk verborgen live kan gaan en aangezet (of weer uitgezet) kan worden zonder nieuwe release.","also":["feature flags","feature toggle","functieschakelaar"]},{"id":"rollfwd","g":"change","word":"Vooruitrollen","text":"Een slechte release herstellen door snel een nieuwe, verbeterde versie uit te brengen in plaats van terug te gaan naar de oude.","also":["roll forward"]},{"id":"canary","g":"change","word":"Canary-release","text":"Een wijziging eerst live zetten voor een kleine groep, en pas voor iedereen als het goed lijkt te gaan. Genoemd naar de kanaries die mijnwerkers meenamen als vroege waarschuwing.","also":["canary release","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Twee kopieën van het live systeem klaarhouden en mensen in één keer naar de nieuwe overzetten, zodat je meteen terug kunt als het misgaat.","also":["blue-green","blauw-groen"]},{"id":"zerodown","g":"change","word":"Deployment zonder downtime","text":"Een nieuwe versie live zetten zonder dat de dienst ook maar even stilvalt voor de gebruikers.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Wijzigingsbeheer","text":"Wijzigingen laten slagen: het risico afwegen, de juiste goedkeuring krijgen en een goed moment kiezen. Ook wel change management genoemd.","also":["change management","change enablement"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"Een groep die belangrijke wijzigingen bekijkt en afspreekt of en wanneer ze door mogen gaan.","also":["CAB","wijzigingsraad"]},{"id":"stdchange","g":"change","word":"Standaardwijziging","text":"Een wijziging met weinig risico die elke keer op dezelfde, beproefde manier gebeurt, en daarom vooraf goedgekeurd is.","also":["standaardwijzigingen","standard change"]},{"id":"normchange","g":"change","word":"Normale wijziging","text":"Een wijziging die eerst gecontroleerd en goedgekeurd moet worden voordat ze doorgaat.","also":["normale wijzigingen","normal change"]},{"id":"emergchange","g":"change","word":"Spoedwijziging","text":"Een wijziging die meteen moet gebeuren om ernstige problemen op te lossen of te voorkomen, met een snellere goedkeuring die daarbij past.","also":["spoedwijzigingen","emergency change"]},{"id":"automation","g":"change","word":"Automatisering","text":"De computer een terugkerende klus vanzelf laten doen, zodat het sneller gaat en elke keer op dezelfde manier.","also":["geautomatiseerd","automatiseren"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructuur","text":"De machines, netwerken en diensten waarop software draait.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Je servers en instellingen beschrijven in bestanden die bij de code horen, zodat je ze elke keer precies hetzelfde kunt opbouwen.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Computers, opslag en diensten via het internet huren bij een grote aanbieder, in plaats van zelf de machines te bezitten.","also":["de cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloudaanbieder","text":"Een bedrijf dat rekenkracht via het internet verhuurt, zoals Amazon Web Services (AWS), Microsoft Azure of Google Cloud.","also":["cloudaanbieders","cloudprovider"]},{"id":"hosting","g":"change","word":"Hosting","text":"Waar je app of website staat en draait zodat mensen erbij kunnen, meestal gehuurd bij een bedrijf."},{"id":"domain","g":"change","word":"Domeinnaam","text":"Het webadres dat mensen intypen, zoals example.com. Je huurt het per jaar, dus het moet verlengd worden.","also":["domeinnamen","domein"]},{"id":"dns","g":"change","word":"DNS","text":"Kort voor domain name system: het adresboek van het internet, dat een naam zoals example.com omzet in het adres van de juiste computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Een afgesloten pakket met een app en alles wat ze nodig heeft, zodat ze op elke computer hetzelfde draait. Docker is de bekendste tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuele machine (VM)","text":"Een nagebootste computer die in een echte draait, zodat één grote machine zich als vele kan gedragen.","also":["VM","VM’s","virtuele machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Code draaien zonder zelf servers te onderhouden: de aanbieder voert ze uit wanneer nodig en je betaalt voor wat je gebruikt."},{"id":"lb","g":"change","word":"Loadbalancer","text":"Iets wat bezoekers over meerdere servers verdeelt, zodat er niet één overspoeld raakt.","also":["loadbalancers","load balancer"]},{"id":"cache","g":"change","word":"Cache","text":"Een handige voorraad recente resultaten dichtbij, zodat hetzelfde niet opnieuw opgehaald of uitgerekend hoeft te worden. Hem leegmaken helpt soms als een pagina verouderd lijkt.","also":["caches","cachen","gecachet"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"Een wereldwijd net van servers met kopieën van je pagina’s en afbeeldingen dicht bij je bezoekers, zodat ze snel laden.","also":["CDN"]},{"id":"migration","g":"change","word":"Migratie","text":"Gegevens of systemen van een oude opstelling naar een nieuwe verhuizen, of zorgvuldig aanpassen hoe een database is ingedeeld.","also":["migraties","databasemigratie"]},{"id":"service","g":"run","word":"Dienst","text":"Iets wat je gebouwd hebt en waar mensen op rekenen, zoals een website of een app, waar je voor zorgt zodat het blijft werken. Vink “Dit project is een dienst” aan en zeg wat het biedt, wie het gebruikt en wie wachtdienst heeft.","also":["diensten"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Hoeveel van de tijd een dienst werkt, meestal als percentage. Bij 99,9% mag hij nog zo’n 43 minuten per maand plat liggen.","also":["beschikbaarheidstijd"]},{"id":"uptime","g":"run","word":"Uptimecontrole","text":"Een automatische controle, om de paar minuten, of je dienst nog antwoordt. Mislukt die een paar keer na elkaar, dan opent AI-gile vanzelf een incidentkaart.","also":["uptimecontroles"]},{"id":"statuspage","g":"run","word":"Statuspagina","text":"Een openbare pagina die toont of een dienst werkt (groen, oranje of rood) met de laatste update, zodat de mensen die hem gebruiken kunnen kijken in plaats van te vragen.","also":["statuspagina's"]},{"id":"desk","g":"run","word":"Servicedesk","text":"De plek waar vragen en meldingen binnenkomen van de mensen die je dienst gebruiken. AI-gile deelt elke melding in als verzoek, incident of idee, en zegt het als iets lijkt op wat al gemeld is.","also":["servicedesks","service desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Serviceverzoek","text":"Iemand die om iets gewoons vraagt, zoals een nieuw account of een beetje hulp, in plaats van te melden dat er iets kapot is. Het wacht op zijn beurt; een incident gaat voor.","also":["serviceverzoeken"]},{"id":"incident","g":"run","word":"Incident","text":"Iets wat nu stuk is of niet goed werkt voor de mensen die het gebruiken, zoals een website die plat ligt of heel traag is. Een 🔥 incidentkaart gaat voor: het weer aan de praat krijgen komt eerst.","also":["incidenten"]},{"id":"major","g":"run","word":"Groot incident","text":"Een groot incident: veel mensen getroffen, of geld of gegevens in gevaar. Eén knop zet elk team erop (zwerm), wekt wie wachtdienst heeft en vraagt elke 30 minuten een statusupdate.","also":["grote incidenten"]},{"id":"oncall","g":"run","word":"Wachtdienst","text":"De persoon die reageert als er iets stukgaat, ook ’s nachts. Elke dienst heeft een teamlid met wachtdienst dat als eerste gewekt wordt voor zijn incidenten.","also":["van wacht","dienstdoend","dienstdoende"]},{"id":"replyby","g":"run","word":"Antwoordtijd","text":"Hoe lang een kaart mag wachten op een eerste antwoord, bijvoorbeeld een uur voor een incident. Daarna krijgt ze een rode klok, zodat niets stilletjes vergeten wordt. Ook wel reactietermijn genoemd.","also":["antwoordtijden","reactietermijn"]},{"id":"postmortem","g":"run","word":"Nabespreking","text":"Een korte terugblik na een incident: wat er gebeurde, wat hielp en wat er moet veranderen, zonder iemand de schuld te geven. Een incident kan niet afgesloten worden zonder.","also":["nabesprekingen","postmortem"]},{"id":"problem","g":"run","word":"Probleem","text":"De verborgen oorzaak achter een of meer incidenten. Een 🧩 probleemkaart bundelt incidenten die blijven terugkomen, zodat de oorzaak gevonden en voorgoed opgelost wordt.","also":["problemen"],"noTip":1},{"id":"rootcause","g":"run","word":"Grondoorzaak","text":"De echte reden waarom iets stukging, niet alleen wat je zag misgaan. Los de grondoorzaak op en het incident komt niet meer terug.","also":["grondoorzaken"]},{"id":"workaround","g":"run","word":"Workaround","text":"Een manier om alles werkend te houden tot de echte oplossing klaar is, zoals iets herstarten als het vastloopt. Ze staat op de probleemkaart, zodat niemand het opnieuw moet uitzoeken.","also":["workarounds","noodoplossing","noodoplossingen"]},{"id":"knownerror","g":"run","word":"Bekende fout","text":"Een probleem waarvan de oorzaak bekend is maar dat nog niet opgelost is, meestal met een workaround erbij. 🧩 Bekende fouten zet ze op een rij, zodat iedereen de workaround gebruikt in plaats van opnieuw te zoeken.","also":["bekende fouten"]},{"id":"runbook","g":"run","word":"Runbook","text":"Stap-voor-stapinstructies om een bekend soort probleem op te lossen, zodat het telkens op dezelfde manier en snel gebeurt. Na een groot incident kan het team er een voorstellen die jij goedkeurt.","also":["runbooks"]},{"id":"ci","g":"run","word":"Configuratie-item","text":"Iets waar je dienst op leunt, zoals een server, een domein, een certificaat, een sleutel of een leverancier. 🗂️ Configuratie-items zet ze per dienst op een rij, zodat je ziet wat een incident raakt en wat vernieuwd of geback-upt moet worden.","also":["configuratie-items","configuration item","configuration items"]},{"id":"expiry","g":"run","word":"Vervaldatum","text":"De datum waarop iets stopt met werken als je het niet vernieuwt, zoals het beveiligingscertificaat of het webadres van een website. AI-gile houdt die data in de gaten en maakt 30 dagen vooraf één kaart om het te vernieuwen, zodat niets onverwacht stopt.","also":["vervaldata","vervaldatums","verloopdatum"]},{"id":"backup","g":"run","word":"Back-up","text":"Een bewaarde kopie van je gegevens van eerder, om op terug te vallen als er iets verloren gaat of beschadigd raakt. AI-gile maakt elke dag een back-up van je borden.","also":["back-ups","backup","backups"]},{"id":"restore","g":"run","word":"Terugzetten","text":"Gegevens terugzetten uit een back-up. Een back-up telt pas echt als je weet dat je hem kunt terugzetten, dus probeer het af en toe eens.","also":["teruggezet"]},{"id":"svcreview","g":"run","word":"Maandterugblik","text":"Een terugblik op één maand van een dienst: geopende en opgeloste incidenten, hoe snel mensen antwoord kregen, beschikbaarheid en gebruikte tokens. De Maandterugblik toont het per dienst.","also":["maandterugblikken","service review"]},{"id":"accessreview","g":"run","word":"Toegangscontrole","text":"Elke 90 dagen nagaan wie er nog in kan: deellinks, rollen van vrienden en bewaarde wachtwoorden en sleutels. Je houdt of verwijdert ze een voor een, zodat oude toegang niet blijft hangen.","also":["toegangscontroles","access review"]},{"id":"improvements","g":"run","word":"Verbeterlijst","text":"Alles waar het team beter in wil worden, op één plek: suggesties uit de retro, acties uit terugblikken en oplossingen voor problemen, elk met de stand van zaken. Je vindt het onder 📈 Verbeteringen.","also":["verbeterlijsten","verbeteringen"]},{"id":"tokencap","g":"run","word":"Tokenlimiet","text":"Een maandelijkse grens aan de tokens die de agents van een dienst mogen gebruiken. Bij 80% krijg je een waarschuwing; bij 100% wacht hun werk op de achtergrond tot volgende maand of tot je de limiet verhoogt.","also":["tokenlimieten","token cap"]},{"id":"svcmgmt","g":"run","word":"Servicemanagement","text":"Alles wat erbij komt kijken om een dienst dag na dag nuttig en werkend te houden voor de mensen die erop rekenen.","also":["dienstbeheer","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Een veelgebruikte gids voor goed servicemanagement, over onder meer incidenten, problemen en wijzigingen. De naam stond ooit voor IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT-servicemanagement (ITSM)","text":"Technologie als een dienst voor mensen aanbieden, met duidelijke afspraken over verzoeken, incidenten, wijzigingen en verbeteringen.","also":["ITSM"]},{"id":"managed","g":"run","word":"Beheerde dienst","text":"Een dienst die iemand anders voor je draait en onderhoudt, met een afspraak over hoe goed die moet werken.","also":["beheerde diensten","managed service"]},{"id":"svcowner","g":"run","word":"Service-eigenaar","text":"De persoon die verantwoordelijk is voor een dienst als geheel: hoe goed die werkt, wat die kost en hoe die beter wordt.","also":["service-eigenaars","service owner"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"Een schriftelijke belofte aan klanten over hoe goed een dienst werkt, zoals “99,9% van de tijd in de lucht” of “binnen een uur antwoord”, vaak met geld terug als die belofte gebroken wordt.","also":["SLA","SLA’s","SLA's","dienstverleningsovereenkomst"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"Het eigen doel van het team voor hoe goed een dienst over een periode moet werken, meestal iets strenger dan de SLA, voor de zekerheid.","also":["SLO","SLO’s"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"De echte meting die je naast een doel legt, zoals het aandeel bezoeken dat goed laadde.","also":["SLI","SLI’s"]},{"id":"availability","g":"run","word":"Beschikbaarheid","text":"Of mensen een dienst kunnen gebruiken wanneer ze die nodig hebben, vaak gemeten als uptime.","also":["availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Tijd waarin een dienst niet werkt of uitstaat, gepland of niet.","also":["uitvaltijd"]},{"id":"errorbudget","g":"run","word":"Foutbudget","text":"De kleine hoeveelheid falen die je betrouwbaarheidsdoel toelaat. Zolang er nog over is, kun je risico nemen met wijzigingen; is het op, dan doe je het rustiger aan.","also":["foutbudgetten","error budget"]},{"id":"outage","g":"run","word":"Storing","text":"Een periode waarin een dienst plat ligt of zwaar stuk is voor de gebruikers.","also":["storingen","uitval","outage"]},{"id":"degraded","g":"run","word":"Verminderd","text":"Werkt wel, maar slecht: traag, of met sommige onderdelen die het niet doen.","also":["verminderde werking","degraded"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Een dienst automatisch en voortdurend in de gaten houden, zodat problemen opvallen, liefst voordat gebruikers ze merken.","also":["bewaking"]},{"id":"observability","g":"run","word":"Observeerbaarheid","text":"Hoe goed je van buitenaf kunt zien wat er in een systeem gebeurt, aan de hand van logs, cijfers en traces.","also":["observability"]},{"id":"log","g":"run","word":"Log","text":"Een doorlopend dagboek dat een programma bijhoudt van wat het doet, om uit te zoeken wat er misging.","also":["logs","logboek"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Een verslag van hoe één verzoek stap voor stap door de onderdelen van een systeem reist, zodat je ziet waar het vertraagde.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latentie","text":"Hoe lang iets erover doet om te antwoorden, zoals de wachttijd tussen klikken en de pagina die verschijnt.","also":["latency"]},{"id":"alert","g":"run","word":"Melding","text":"Een automatisch bericht dat iets aandacht nodig heeft, zoals de website die niet antwoordt.","also":["meldingen","alert","alerts"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Meldingsmoeheid","text":"Als er zoveel meldingen zijn dat mensen ze gaan negeren, ook de belangrijke.","also":["alert fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Een scherm dat de belangrijkste cijfers en statussen in één oogopslag toont.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Oppiepen","text":"De persoon met wachtdienst dringend bellen of wekken voor een probleem.","also":["opgepiept","paging"]},{"id":"escalation","g":"run","word":"Escalatie","text":"Iemand met meer kennis of zeggenschap erbij halen als een probleem op het huidige niveau niet, of niet snel genoeg, opgelost raakt.","also":["escaleren","geëscaleerd"]},{"id":"triage","g":"run","word":"Triage","text":"Binnenkomende meldingen snel sorteren op hoe dringend en belangrijk ze zijn, zodat het ergste eerst aangepakt wordt.","also":["triëren","getrieerd"]},{"id":"impact","g":"run","word":"Impact","text":"Hoeveel iets mensen raakt: hoeveel mensen, en hoe erg.","noTip":1},{"id":"urgency","g":"run","word":"Urgentie","text":"Hoe snel iets aangepakt moet worden. Impact en urgentie samen bepalen de prioriteit.","noTip":1},{"id":"plevels","g":"run","word":"Prioriteitsniveaus (P1, P2…)","text":"Labels voor hoe dringend een probleem is. P1 is het ernstigst en vraagt meteen actie.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticketwachtrij","text":"De lijst met verzoeken en incidenten die wachten tot iemand ze oppakt.","also":["ticketwachtrijen","ticket queue"]},{"id":"tiers","g":"run","word":"Eerste en tweede lijn","text":"Niveaus van ondersteuning: de eerste lijn neemt de melding aan en lost eenvoudige dingen op; de tweede lijn heeft diepere kennis voor moeilijkere. Ook wel tier 1 en tier 2.","also":["eerste lijn","tweede lijn","eerstelijns","tweedelijns"]},{"id":"ic","g":"run","word":"Incidentcoördinator","text":"De ene persoon die de aanpak van een incident leidt, zodat iedereen weet wie beslist en wie wat doet.","also":["incidentcoördinatoren","incident commander"]},{"id":"responsetime","g":"run","word":"Reactietijd","text":"Hoe lang het duurt voordat iemand een verzoek of incident voor het eerst oppakt.","also":["reactietijden","responstijd"]},{"id":"resolution","g":"run","word":"Oplostijd","text":"Hoe lang het duurt om een verzoek of incident helemaal af te handelen, van melding tot opgelost.","also":["oplostijden","doorlooptijd van een melding"]},{"id":"mttr","g":"run","word":"Gemiddelde hersteltijd (MTTR)","text":"Hoe lang het gemiddeld duurt om een dienst weer aan de praat te krijgen nadat ze stukging. MTTR kan net iets anders betekenen, dus zeg wat je meet.","also":["MTTR","mean time to recover"]},{"id":"mtbf","g":"run","word":"Gemiddelde tijd tussen storingen (MTBF)","text":"Hoe lang een dienst gemiddeld draait voordat er iets stukgaat.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuratiedatabase (CMDB)","text":"De lijst van al je configuratie-items en hoe ze samenhangen, zodat je ziet wat van wat afhangt.","also":["CMDB"]},{"id":"asset","g":"run","word":"Bedrijfsmiddel","text":"Alles van waarde dat je bezit of betaalt om de dienst te draaien, zoals een laptop, een softwarelicentie of een domein.","also":["bedrijfsmiddelen","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capaciteitsplanning","text":"Zorgen dat er genoeg rekenkracht, opslag en mensen zijn voor wat er aankomt.","also":["capacity planning"]},{"id":"scaling","g":"run","word":"Schalen","text":"Meer gebruikers aankunnen door een machine meer kracht te geven (opschalen) of meer machines toe te voegen (uitschalen).","also":["opschalen","uitschalen","scaling"]},{"id":"bcp","g":"run","word":"Bedrijfscontinuïteit","text":"Plannen om het belangrijkste draaiende te houden als er iets groots misgaat, zoals een kantoor, een belangrijke leverancier of de computers verliezen.","also":["continuïteitsplan","business continuity"]},{"id":"dr","g":"run","word":"Noodherstel (disaster recovery)","text":"Het plan en de middelen om een dienst terug te krijgen na iets ernstigs, zoals het verlies van een heel datacenter.","also":["disaster recovery","DR"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"Hoe lang een dienst na een ramp maximaal plat mag liggen voordat hij weer moet werken.","also":["RTO","hersteltijddoel"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"Hoeveel recente gegevens je kunt missen, uitgedrukt in tijd. Een RPO van een uur betekent minstens elk uur een back-up.","also":["RPO","herstelpuntdoel"]},{"id":"redundancy","g":"run","word":"Redundantie","text":"Reserves klaar hebben, zoals een tweede server, zodat één defect de dienst niet stillegt."},{"id":"failover","g":"run","word":"Failover","text":"Vanzelf overschakelen op een reservesysteem als het gewone uitvalt.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"Eén onderdeel dat alles meesleurt als het stukgaat, omdat er geen reserve is.","also":["SPOF"]},{"id":"maintwin","g":"run","word":"Onderhoudsvenster","text":"Een gepland moment waarop een dienst even stil of traag mag zijn voor onderhoud, vooraf aangekondigd aan de gebruikers.","also":["onderhoudsvensters","gepland onderhoud"]},{"id":"handover","g":"run","word":"Overdracht","text":"Werk, kennis en verantwoordelijkheid doorgeven aan een andere persoon of een ander team, zodat er niets tussen de mazen valt.","also":["overdrachten"]},{"id":"kb","g":"run","word":"Kennisbank","text":"Een verzameling hulpartikels en antwoorden, voor gebruikers en voor het team.","also":["kennisbanken","knowledge base"]},{"id":"csat","g":"run","word":"Klanttevredenheid (CSAT)","text":"Een score van gebruikers over hoe tevreden ze waren, vaak gevraagd nadat een verzoek is afgesloten.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Leverancier","text":"Een bedrijf van buiten waar je op rekent, zoals je hostingaanbieder. Ook wel derde partij genoemd.","also":["leveranciers","derde partij"],"noTip":1},{"id":"retire","g":"run","word":"Uitfaseren","text":"Een dienst veilig en voorgoed uitzetten: de gebruikers inlichten, de gegevens en toegang afhandelen en de kosten stopzetten.","also":["uitfasering","een dienst uitfaseren"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"Als een product geen updates of ondersteuning meer krijgt van de maker, zodat je het best vervangt.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cyberbeveiliging","text":"Systemen en gegevens beschermen tegen inbraak, diefstal of schade.","also":["cybersecurity"]},{"id":"authn","g":"sec","word":"Authenticatie","text":"Nagaan wie iemand is, meestal met een wachtwoord of een code. Vaak afgekort tot authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Autorisatie","text":"Nagaan wat iemand mag doen, als je eenmaal weet wie het is. Vaak afgekort tot authz.","also":["authz"]},{"id":"mfa","g":"sec","word":"Meerstapsverificatie (MFA)","text":"Inloggen met twee of meer bewijzen, zoals een wachtwoord plus een code op je telefoon. Ook wel tweestapsverificatie (2FA).","also":["MFA","2FA","tweestapsverificatie","multi-factor authenticatie"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Eén keer inloggen om in veel systemen te komen, zoals overal je werkaccount gebruiken.","also":["SSO","eenmalig inloggen"]},{"id":"pwmgr","g":"sec","word":"Wachtwoordbeheerder","text":"Een app die sterke wachtwoorden maakt en ze voor je onthoudt.","also":["wachtwoordbeheerders","wachtwoordmanager","password manager"]},{"id":"secret","g":"sec","word":"Geheim","text":"Een wachtwoord, sleutel of andere privécode die een programma gebruikt om ergens binnen te komen. Nooit delen en nooit in de code zetten.","also":["geheimen","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API-sleutel","text":"Een geheime code waarmee een programma de API van een andere dienst mag gebruiken, en die laat zien wie ze gebruikt (en betaalt).","also":["API-sleutels","API key"]},{"id":"accesstoken","g":"sec","word":"Toegangstoken","text":"Een tijdelijke pas die bewijst dat een programma binnen mag, zodat het niet telkens je wachtwoord nodig heeft. Niet hetzelfde als een AI-token.","also":["toegangstokens","access token"]},{"id":"encryption","g":"sec","word":"Versleuteling","text":"Informatie zo door elkaar husselen dat alleen wie de juiste sleutel heeft ze kan lezen.","also":["versleuteld","versleutelen","encryptie"]},{"id":"https","g":"sec","word":"HTTPS","text":"De beveiligde manier waarop webpagina’s reizen, te zien aan het slotje in je browser, zodat niemand onderweg ze kan lezen of aanpassen."},{"id":"cert","g":"sec","word":"SSL/TLS-certificaat","text":"Een digitale identiteitskaart waarmee een website bewijst wie ze is en HTTPS kan gebruiken. Het verloopt, dus het moet vernieuwd worden.","also":["TLS-certificaat","SSL-certificaat","certificaat","certificaten"]},{"id":"permissions","g":"sec","word":"Rechten","text":"De regels over wie wat mag zien of aanpassen.","also":["machtigingen","permissies"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Minimale rechten","text":"Elke persoon of elk programma alleen de toegang geven die echt nodig is, en alleen zo lang als nodig.","also":["least privilege"]},{"id":"rbac","g":"sec","word":"Rolgebaseerde toegang (RBAC)","text":"Toegang geven per rol, zoals kijker of bewerker, in plaats van per persoon.","also":["RBAC"]},{"id":"vuln","g":"sec","word":"Kwetsbaarheid","text":"Een zwakke plek die iemand kan gebruiken om in te breken of schade aan te richten.","also":["kwetsbaarheden"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Een zwakke plek die aanvallers kennen voordat de makers de kans kregen om ze te dichten.","also":["zero-days","zerodaylek"]},{"id":"malware","g":"sec","word":"Malware","text":"Schadelijke software, zoals virussen, gemaakt om te beschadigen, te bespioneren of te stelen."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware die je bestanden op slot zet en geld vraagt om ze weer vrij te geven. Goede back-ups zijn de beste verdediging.","also":["gijzelsoftware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Valse berichten die je proberen te verleiden om wachtwoorden of geld af te geven, of iets schadelijks te openen.","also":["phishingmail","phishingmails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Mensen in plaats van computers misleiden om toegang te krijgen, zoals een nep-telefoontje van “de IT-helpdesk”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Een bewaker die beslist welk netwerkverkeer binnen of buiten mag.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kort voor virtual private network: een privé, versleutelde verbinding over het internet, vaak gebruikt om veilig bij werksystemen te komen.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Een dienst overspoelen met zoveel nepverkeer dat echte mensen hem niet meer kunnen gebruiken. Bij DDoS komt het van veel computers tegelijk.","also":["DoS","DDoS","DDoS-aanval"]},{"id":"pentest","g":"sec","word":"Penetratietest (pentest)","text":"Vriendelijke experts inhuren die proberen in te breken, zodat zwakke plekken gevonden worden voordat echte aanvallers ze vinden.","also":["pentest","pentesten","penetratietesten"]},{"id":"audit","g":"sec","word":"Beveiligingsaudit","text":"Een grondige controle van hoe goed iets beschermd is, tegen een lijst van goede praktijken.","also":["beveiligingsaudits","security audit"]},{"id":"threatmodel","g":"sec","word":"Dreigingsmodel","text":"Doordenken wie iets zou kunnen aanvallen, hoe, en wat je zou doen om dat te stoppen.","also":["dreigingsmodellering","threat model"]},{"id":"breach","g":"sec","word":"Datalek","text":"Als privé-informatie terechtkomt bij mensen die ze niet mogen hebben, of zonder toestemming verloren gaat of veranderd wordt.","also":["datalekken","data breach"]},{"id":"pii","g":"sec","word":"Persoonsgegevens","text":"Alle informatie over een persoon die herkenbaar is, zoals een naam, een e-mailadres of een locatie.","also":["persoonsgegeven","PII"]},{"id":"gdpr","g":"sec","word":"AVG (GDPR)","text":"De Europese wet over persoonsgegevens: verzamel alleen wat je nodig hebt, bewaar het veilig, en laat mensen hun gegevens inzien of wissen.","also":["AVG","GDPR","Algemene verordening gegevensbescherming"]},{"id":"dataprot","g":"sec","word":"Gegevensbescherming","text":"Goed en volgens de wet omgaan met persoonsgegevens.","also":["databescherming","data protection"]},{"id":"privacypolicy","g":"sec","word":"Privacyverklaring","text":"Een openbare pagina die zegt welke persoonsgegevens je verzamelt, waarom, en wat je ermee doet.","also":["privacybeleid","privacy policy"]},{"id":"consent","g":"sec","word":"Toestemming","text":"Het duidelijke, vrije ja van iemand om zijn gegevens op een bepaalde manier te gebruiken. Die kan hij altijd weer intrekken.","also":["consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Een klein bestandje dat een website in je browser bewaart om dingen te onthouden, zoals dat je ingelogd bent. Voor sommige is eerst je toestemming nodig.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Dataminimalisatie","text":"Alleen de persoonsgegevens verzamelen en bewaren die je echt nodig hebt.","also":["data minimisation"]},{"id":"retention","g":"sec","word":"Bewaartermijn","text":"Hoe lang gegevens bewaard worden voordat ze gewist worden. Niet langer bewaren dan nodig is veiliger en vaak verplicht.","also":["bewaartermijnen","data retention"]},{"id":"anon","g":"sec","word":"Anonimiseren","text":"Gegevens zo aanpassen dat niemand er redelijkerwijs nog uit te herkennen is.","also":["geanonimiseerd","anonimisering"]},{"id":"pseudo","g":"sec","word":"Pseudonimiseren","text":"Namen en andere gegevens vervangen door codes, met een sleutel apart bewaard om ze terug te koppelen. Het blijven persoonsgegevens.","also":["gepseudonimiseerd","pseudonimisering"]},{"id":"dpa","g":"sec","word":"Verwerkersovereenkomst","text":"Een contract dat zegt hoe een leverancier namens jou met persoonsgegevens mag omgaan.","also":["verwerkersovereenkomsten","DPA"]},{"id":"dpia","g":"sec","word":"Gegevensbeschermingseffectbeoordeling (DPIA)","text":"Een grondige blik, voordat je begint, op hoe een plan met persoonsgegevens mensen kan raken en hoe je de risico’s verkleint.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Auditlog","text":"Een verslag van wie wat deed en wanneer, zodat je het later kunt nagaan.","also":["auditlogs","audittrail","audit log"]},{"id":"compliance","g":"sec","word":"Compliance","text":"De wetten, regels en normen volgen die voor jou gelden, en kunnen aantonen dat je dat doet.","also":["naleving"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Een bekende internationale norm voor het beheren van informatiebeveiliging. Bedrijven kunnen ervoor gecertificeerd worden.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Een Amerikaans rapport, nagekeken door externe auditors, dat laat zien dat een bedrijf goed omgaat met klantgegevens.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Een AI die zelfstandig aan een taak werkt: leest de code, maakt wijzigingen, draait controles en meldt terug. Het werk wordt daarna nog nagekeken.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"De kleine stukjes tekst die een AI leest en schrijft, ongeveer driekwart woord per stuk. AI-gebruik wordt in tokens geteld, dus minder tokens laten meer van je abonnement over.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Een kleine opdracht die vanzelf draait op een vast moment, bijvoorbeeld als een AI-sessie start, zodat het team je reacties hoort.","also":["hooks"]},{"id":"ai","g":"ai","word":"Kunstmatige intelligentie (AI)","text":"Computersystemen die dingen doen waarvan we denken dat er een mens voor nodig is, zoals schrijven, vragen beantwoorden of afbeeldingen herkennen.","also":["AI","artificiële intelligentie"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"Computers patronen laten leren uit heel veel voorbeelden, in plaats van ze precieze regels te geven.","also":["machine learning","machinaal leren"]},{"id":"model","g":"ai","word":"Model","text":"Het getrainde “brein” van een AI-systeem, gebouwd door te leren van enorm veel voorbeelden. Modellen verschillen in kunde, snelheid en prijs.","also":["modellen","AI-model"],"noTip":1},{"id":"llm","g":"ai","word":"Groot taalmodel (LLM)","text":"Een AI-model dat getraind is op enorme hoeveelheden tekst, zodat het taal kan lezen en schrijven.","also":["LLM","LLM’s","taalmodel"]},{"id":"genai","g":"ai","word":"Generatieve AI","text":"AI die nieuwe dingen maakt, zoals tekst, afbeeldingen of code, in plaats van ze alleen te sorteren of te herkennen.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Een programma waarmee je in gewone taal praat, door te typen of te spreken.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Wat je een AI geeft: je vraag of opdracht, plus alles wat je erbij aanreikt. Duidelijkere prompts geven meestal betere antwoorden.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"De kunst van prompts schrijven die betrouwbare, bruikbare resultaten geven."},{"id":"sysprompt","g":"ai","word":"Systeemprompt","text":"Achtergrondinstructies die een AI krijgt voordat het gesprek begint, met zijn rol en regels. Die wegen zwaarder dan wat jij typt.","also":["systeemprompts","system prompt"]},{"id":"context","g":"ai","word":"Context","text":"Alles wat de AI kan zien terwijl hij werkt: de instructies, je berichten, bestanden die hij las en eerdere antwoorden.","noTip":1},{"id":"ctxwin","g":"ai","word":"Contextvenster","text":"Hoeveel een AI tegelijk kan onthouden, gemeten in tokens. Daarboven vallen oudere delen weg of worden ze samengevat.","also":["contextvensters","context window"]},{"id":"session","g":"ai","word":"Sessie","text":"Eén werkgesprek met een AI, van begin tot eind. Een nieuwe sessie begint met een leeg geheugen.","also":["sessies"],"noTip":1},{"id":"memory","g":"ai","word":"Geheugen","text":"Notities die een AI tussen sessies bewaart, zodat hij je voorkeuren en eerdere beslissingen onthoudt.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucinatie","text":"Als een AI iets zegt dat zelfverzekerd klinkt maar verzonnen of fout is. Controleer belangrijke feiten.","also":["hallucinaties","hallucineren","hallucineert"]},{"id":"training","g":"ai","word":"Training","text":"Een model iets leren door het enorm veel voorbeelden te tonen, voordat iemand het gebruikt.","also":["trainen","getraind"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Trainingsdata","text":"De voorbeelden waar een model van leerde. Zijn kennis stopt op de datum dat die gegevens verzameld werden.","also":["trainingsgegevens","training data"]},{"id":"cutoff","g":"ai","word":"Kennisgrens","text":"De datum waarop de ingebouwde kennis van een AI ophoudt. Over latere dingen weet hij niets, tenzij hij ze opzoekt.","also":["knowledge cutoff"]},{"id":"finetune","g":"ai","word":"Finetunen","text":"Een bestaand model extra trainen op je eigen voorbeelden, zodat het beter wordt in één bepaalde klus.","also":["fine-tuning","gefinetuned"]},{"id":"inference","g":"ai","word":"Inferentie","text":"Een AI-model dat echt gebruikt wordt om iets te beantwoorden, in tegenstelling tot getraind worden.","also":["inference"]},{"id":"tooluse","g":"ai","word":"Toolgebruik","text":"Een AI die dingen kan doen, niet alleen praten: opdrachten uitvoeren, bestanden lezen of het web doorzoeken, met tools die de app hem geeft.","also":["tool use","tool calling","tool call"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Een helper-AI waaraan een hoofd-AI een kleinere klus doorgeeft, en die het resultaat terugbrengt.","also":["subagents"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Meerdere AI’s die samen aan één stuk werk werken, elk met een eigen deel, zoals een klein team.","also":["multi-agentsysteem"]},{"id":"autonomy","g":"ai","word":"Autonomie","text":"Hoeveel een AI op eigen houtje mag doen voordat hij het een mens moet vragen.","also":["autonoom"]},{"id":"hitl","g":"ai","word":"Mens in de lus","text":"Een mens betrokken houden die op belangrijke momenten controleert of goedkeurt wat de AI doet. In AI-gile ben jij dat.","also":["human in the loop","human-in-the-loop"]},{"id":"guardrails","g":"ai","word":"Vangrails","text":"Grenzen en controles die wat een AI doet veilig houden, zoals goedkeuring nodig hebben voordat iets live gaat. Ze verkleinen het risico op fouten, maar sluiten het niet uit.","also":["vangrail","guardrails"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Een AI eerst laten opzoeken in je eigen documenten voordat hij antwoordt, zodat zijn antwoorden op jouw feiten steunen.","also":["RAG"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Tekst omzetten in een rij getallen die de betekenis vangt, zodat een computer dingen met een vergelijkbare betekenis kan vinden.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vectordatabase","text":"Een database die gemaakt is om in die rijen getallen (embeddings) te zoeken, om materiaal met een vergelijkbare betekenis te vinden.","also":["vectordatabases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Een gangbare manier om tools en gegevensbronnen aan AI-apps te koppelen, zodat een AI ze kan gebruiken.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatuur","text":"Een instelling voor hoe avontuurlijk de antwoorden van een AI zijn. Laag geeft vastere, voorspelbaardere antwoorden; hoog meer gevarieerde. Geen van beide maakt hem altijd juist.","also":["temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodaal","text":"Kan met meer dan één soort informatie werken, zoals tekst, afbeeldingen en geluid.","also":["multimodal"]},{"id":"evals","g":"ai","word":"Evaluatie (eval)","text":"Een geplande test van hoe goed een AI het doet op gekozen voorbeelden, zodat je modellen of prompts kunt vergelijken.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Vooringenomenheid","text":"Als een AI (of een mens) oneerlijk naar één kant overhelt, vaak door waar hij van leerde.","also":["bias","vooringenomen"],"noTip":1},{"id":"responsible","g":"ai","word":"Verantwoorde AI","text":"AI eerlijk, veilig en open gebruiken, waarbij mensen verantwoordelijk blijven voor het resultaat.","also":["responsible AI"]},{"id":"injection","g":"ai","word":"Promptinjectie","text":"Een truc waarbij verborgen instructies in een webpagina of bestand een AI iets proberen te laten doen waar de gebruiker niet om vroeg.","also":["prompt injection"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"Een plafond voor hoeveel verzoeken je in een bepaalde tijd naar een dienst mag sturen. Ga je erover, dan moet je wachten.","also":["rate limits","aanvraaglimiet"]},{"id":"usagelimit","g":"ai","word":"Gebruikslimiet","text":"Hoeveel AI-werk je abonnement in een periode toelaat, waarna het pauzeert of meer kost.","also":["gebruikslimieten"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Software bouwen door vooral aan een AI te beschrijven wat je wilt en hem de code te laten schrijven.","also":["vibecoding"]},{"id":"budget","g":"money","word":"Budget","text":"Het geld dat voor iets opzij is gezet.","also":["budgetten"],"noTip":1},{"id":"costest","g":"money","word":"Kostenraming","text":"Een beste gok van wat iets gaat kosten, voordat je begint.","also":["kostenramingen","kostenschatting"]},{"id":"roi","g":"money","word":"Rendement (ROI)","text":"Wat je terugkrijgt vergeleken met wat je erin stak. Is het positief, dan was het de moeite waard.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Totale eigendomskosten (TCO)","text":"Alles wat iets echt kost over de hele levensduur, niet alleen de aankoopprijs: draaien, ondersteuning, upgrades en het uiteindelijk uitfaseren.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx en OpEx","text":"CapEx is geld dat je vooraf uitgeeft aan dingen die je houdt; OpEx zijn doorlopende kosten, zoals maandelijkse rekeningen.","also":["CapEx","OpEx","operationele kosten"]},{"id":"subscription","g":"money","word":"Abonnement","text":"Regelmatig betalen, meestal per maand of per jaar, om iets te blijven gebruiken.","also":["abonnementen"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software die je online gebruikt en via een abonnement betaalt, terwijl de maker ze voor je draait.","also":["SaaS"]},{"id":"payg","g":"money","word":"Betalen naar gebruik","text":"Alleen betalen voor wat je gebruikt, zoals cloudrekenkracht of AI-tokens.","also":["pay-as-you-go","pay as you go"]},{"id":"overage","g":"money","word":"Overschrijding","text":"Gebruik boven wat je abonnement inhoudt, wat extra kan kosten.","also":["meerverbruik","overage"]},{"id":"billingalert","g":"money","word":"Kostenmelding","text":"Een bericht als je uitgaven of gebruik een gekozen grens bereiken. Het waarschuwt je, maar houdt verdere kosten niet altijd tegen.","also":["kostenmeldingen","billing alert"]},{"id":"freetier","g":"money","word":"Gratis niveau","text":"Een gratis niveau van een betaalde dienst, met beperkingen. Handig om mee te beginnen.","also":["gratis abonnement","free tier"]},{"id":"pricing","g":"money","word":"Prijsplan","text":"De verschillende pakketten die een dienst verkoopt, elk met een eigen prijs en eigen grenzen.","also":["prijsplannen","tariefplan"]},{"id":"licence","g":"money","word":"Licentie","text":"De regels voor hoe je iets van iemand anders mag gebruiken, kopiëren, aanpassen of delen, zoals software, lettertypes of afbeeldingen.","also":["licenties"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software waarvan iedereen de code mag lezen, gebruiken en vaak gratis aanpassen, volgens de regels van de licentie.","also":["opensource","open-source","opensourcesoftware","OSS"]},{"id":"osslicence","g":"money","word":"Opensourcelicentie","text":"De regels die bij opensourcecode horen. Sommige laten je bijna alles doen (zoals MIT); andere vragen dat je je aanpassingen ook deelt (zoals GPL).","also":["opensourcelicenties","MIT-licentie","GPL"]},{"id":"proprietary","g":"money","word":"Propriëtair","text":"Eigendom van een bedrijf en niet vrij te kopiëren of aan te passen. Het tegenovergestelde van open source.","also":["propriëtaire software","gesloten software"]},{"id":"copyright","g":"money","word":"Auteursrecht","text":"Het wettelijke recht van een maker om te bepalen wie zijn werk mag kopiëren, ook code en teksten.","also":["auteursrechten","copyright"],"noTip":1},{"id":"ip","g":"money","word":"Intellectueel eigendom (IE)","text":"Ideeën en creaties die de wet als eigendom behandelt, zoals code, ontwerpen, namen en logo’s.","also":["intellectuele eigendom","IE"]},{"id":"tos","g":"money","word":"Gebruiksvoorwaarden","text":"De regels waarmee je akkoord gaat als je een dienst gebruikt.","also":["algemene voorwaarden","terms of service"]},{"id":"contract","g":"money","word":"Contract","text":"Een schriftelijke afspraak tussen twee partijen die de wet ondersteunt.","also":["contracten","overeenkomst"],"noTip":1},{"id":"sow","g":"money","word":"Opdrachtomschrijving (SOW)","text":"Een document dat precies vastlegt welk werk er gedaan wordt, tegen wanneer en voor hoeveel.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Vaste prijs","text":"Een afgesproken prijs voor de hele klus, hoe lang die ook duurt.","also":["fixed price"]},{"id":"tm","g":"money","word":"Regie","text":"Betalen voor de uren die echt gewerkt zijn en de dingen die echt gebruikt zijn, in plaats van een vaste prijs.","also":["op regiebasis","nacalculatie","time and materials"]},{"id":"invoice","g":"money","word":"Factuur","text":"Een rekening die om betaling vraagt voor geleverd werk of geleverde goederen.","also":["facturen"],"noTip":1},{"id":"lockin","g":"money","word":"Leveranciersafhankelijkheid","text":"Als weggaan bij een leverancier zo moeilijk of duur is dat je eraan vastzit.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Inkoopproces","text":"Het proces van leveranciers kiezen en bij hen kopen.","also":["inkoopprocessen","aanbesteding","procurement"]},{"id":"servicecredit","g":"money","word":"Servicecredit","text":"Geld terug of korting die je krijgt als een leverancier zijn SLA niet haalt.","also":["servicecredits","service credit"]}]}};
